-- =====================================================================================================
-- Velexis OTA platform - TENANT schema (one copy per OTA: tenant_<key>), PostgreSQL 16
-- Executed by the provisioner / migration runner inside a transaction AFTER
--   CREATE SCHEMA tenant_<key>;  SET LOCAL search_path TO tenant_<key>, reference;
-- so every name below is UNQUALIFIED and lands in the tenant schema. No CREATE SCHEMA, no SET, no extensions,
-- no foreign keys to other schemas: platform/reference rows are referenced BY VALUE (stf_/key_/sc_ ids, IATA
-- codes, ISO currency codes). No tenant_id column: the schema is the isolation boundary.
--
-- Conventions
--  * id: text primary key = type prefix + ULID generated by the application (time-sortable, so (created_at, id)
--    cursors paginate stably); CHECK (id LIKE '<prefix>\_%') guards against ids of the wrong type.
--    The 80-bit random part of every ULID comes fresh from a CSPRNG for each id (crypto.randomBytes); monotonic
--    ULID generators (which increment the random part within a millisecond) are forbidden. This matters for the
--    capability ids that grant guest access on their own (srch_, off_, prc_, chk_, pay_): their secret is the
--    80 random bits, not the 48-bit timestamp, and guessing attempts are rate-limited per IP and key.
--  * created_at / updated_at timestamptz on every table (updated_at maintained by the application layer; on
--    append-only tables it stays equal to created_at). version = optimistic-locking counter on aggregate roots
--    (a change to a child row bumps the root's version: UPDATE ... SET version = version + 1 WHERE version = $n).
--  * status columns are text + CHECK lists (not enums) so values can be added with an expand-only migration.
--  * money: numeric(12,2) + char(3) ISO 4217 currency. Selling = what the customer pays (after markup/fees),
--    net = what Amadeus charges; net values never leave console scope.
--  * Amadeus payloads are kept verbatim in jsonb (offers, priced offers, flight-order snapshots, redacted
--    supplier requests). Card data is never stored (PCI): only PSP references, brand, BIN and last4.
--  * Identity document numbers and discount (resident card / certificate) numbers are encrypted by the application
--    (AES-256-GCM envelope encryption, KMS key id stored alongside); only last4 / expiry / country stay in clear.
--  * REDACTION RULE for every jsonb copy of an API or supplier payload (bookings.order_snapshot, booking_events.data,
--    staff_actions.before/after, idempotency_keys.response_body, supplier_requests bodies, priced_offers.
--    amadeus_request, payment_events.payload, notifications.payload): before writing, the shared redactor masks
--    documents[].number and discountEligibility[].cardNumber / certificateNumber to their last 4 characters,
--    creditCard.number to its last 4 digits, deletes securityCode / CVV, birthPlace and issuanceLocation, and
--    deletes every token value (access, refresh, booking access, password reset, e-mail verification, portal and
--    API keys). Full values exist only in *_ciphertext columns.
--  * Raw tokens are never stored in clear: tokens are kept as SHA-256 hashes; when a response or an outgoing
--    message must carry a raw token for a while (idempotent replay, e-mail outbox), it is kept only in a
--    *_ciphertext column with its encryption_key_id and is purged when no longer needed.
--  * environment ('test' | 'live') on every supplier- or payment-bound aggregate: set from the X-Api-Key
--    environment; test data uses the tenant's Amadeus test connection and is never mixed with live data.
--  * ON DELETE: CASCADE for children of an aggregate, SET NULL for optional links whose history must survive,
--    RESTRICT for financial links (payments/refunds) and for in-flight dependencies (checkout -> priced offer).
-- Trailing "-- " comments document each column (dictionary.json is generated from them, "* " = shown in ER).
-- =====================================================================================================

-- Per-schema migration ledger (mirrored into platform.tenant_schema_migrations by the migration runner).
CREATE TABLE schema_migrations (
  id           text PRIMARY KEY CHECK (id ~ '^[0-9]{4,14}(_[a-z0-9_]+)?$'),   -- * Migration version, e.g. 0001_baseline (lexicographic order = apply order).
  description  text NOT NULL,                                                -- Human-readable summary of the migration.
  checksum     text NOT NULL,                                                -- SHA-256 of the migration file as applied.
  phase        text NOT NULL DEFAULT 'expand' CHECK (phase IN ('expand','migrate','contract')), -- Expand/contract phase of the change.
  status       text NOT NULL DEFAULT 'applied' CHECK (status IN ('running','applied','failed')), -- * Outcome in this schema.
  execution_ms integer,                                                      -- Execution time in milliseconds.
  created_at   timestamptz NOT NULL DEFAULT now(),                           -- * When the migration was applied.
  updated_at   timestamptz NOT NULL DEFAULT now()                            -- Last status change.
);

-- Single-row storefront configuration of the OTA: branding, locales, currencies, ticketing and payment policy.
CREATE TABLE storefront_settings (
  id                        text PRIMARY KEY DEFAULT 'sfs_default' CHECK (id = 'sfs_default'), -- Fixed id: guarantees exactly one row per tenant.
  brand_name                text NOT NULL,                                   -- * Brand shown in the storefront and e-mails.
  logo_url                  text,                                            -- Logo asset URL.
  favicon_url               text,                                            -- Favicon asset URL.
  primary_color             text CHECK (primary_color ~ '^#[0-9A-Fa-f]{6}$'), -- Primary brand colour (hex).
  secondary_color           text CHECK (secondary_color ~ '^#[0-9A-Fa-f]{6}$'), -- Secondary brand colour (hex).
  theme                     jsonb NOT NULL DEFAULT '{}'::jsonb,              -- Additional design tokens for the Next.js storefront (fonts, radius ...).
  default_locale            text NOT NULL DEFAULT 'en',                      -- * Default locale (BCP 47).
  supported_locales         text[] NOT NULL DEFAULT '{en}',                  -- Locales offered by the storefront.
  default_currency          char(3) NOT NULL DEFAULT 'EUR' CHECK (default_currency ~ '^[A-Z]{3}$'), -- * Default selling currency (Amadeus currencyCode).
  supported_currencies      text[] NOT NULL DEFAULT '{EUR}',                 -- Currencies a customer may choose.
  support_email             text,                                            -- Customer support e-mail shown to travellers.
  support_phone             text,                                            -- Customer support phone.
  ticketing_policy          text NOT NULL DEFAULT 'issue_after_payment'
                            CHECK (ticketing_policy IN ('issue_at_booking','issue_after_payment','manual_review')), -- * When tickets are issued (issue=true at create-order, after capture, or by staff).
  auto_issue                boolean GENERATED ALWAYS AS (ticketing_policy <> 'manual_review') STORED, -- * True when tickets are issued automatically (derived from ticketing_policy).
  payment_timing            text NOT NULL DEFAULT 'authorize_before_booking'
                            CHECK (payment_timing IN ('authorize_before_booking','capture_before_booking','pay_later')), -- Payment requirement relative to create-order (pay_later = hold until ticketing deadline).
  accepted_card_brands      text[] NOT NULL DEFAULT '{VISA,MASTERCARD,AMERICAN_EXPRESS}', -- Card brands accepted (Amadeus PaymentBrand values, for credit-card fees).
  require_3ds               boolean NOT NULL DEFAULT true,                   -- Force 3-D Secure on card payments.
  guest_checkout_enabled    boolean NOT NULL DEFAULT true,                   -- Allow booking without a customer account.
  customer_accounts_enabled boolean NOT NULL DEFAULT true,                   -- Allow customer sign-up / sign-in.
  require_email_verification boolean NOT NULL DEFAULT false,                 -- Customers must verify their e-mail before booking.
  offer_ttl_minutes         integer NOT NULL DEFAULT 30 CHECK (offer_ttl_minutes BETWEEN 5 AND 240), -- Lifetime of cached offers / priced offers.
  checkout_ttl_minutes      integer NOT NULL DEFAULT 30 CHECK (checkout_ttl_minutes BETWEEN 5 AND 1440), -- Lifetime of an open checkout.
  search_defaults           jsonb NOT NULL DEFAULT '{}'::jsonb,              -- Defaults for search forms (max results, nonStop, cabin, sources).
  features                  jsonb NOT NULL DEFAULT '{}'::jsonb,              -- Storefront feature toggles (seat map, upsell, ancillaries).
  terms_url                 text,                                            -- Terms and conditions URL (legal link).
  privacy_url               text,                                            -- Privacy policy URL (legal link).
  legal_links               jsonb NOT NULL DEFAULT '[]'::jsonb,              -- Further legal links [{label, url}] (imprint, cookies, airline conditions).
  version                   integer NOT NULL DEFAULT 1,                      -- Optimistic-locking counter.
  created_at                timestamptz NOT NULL DEFAULT now(),              -- Row creation time (seeded at provisioning).
  updated_at                timestamptz NOT NULL DEFAULT now()               -- Last modification time.
);

-- Markup rules: how the OTA turns Amadeus net prices into selling prices.
CREATE TABLE markup_rules (
  id                  text PRIMARY KEY CHECK (id LIKE 'mkr\_%'),             -- Markup rule id (mkr_ + ULID).
  name                text NOT NULL,                                         -- * Rule name shown in the console.
  description         text,                                                  -- Notes for staff.
  scope               jsonb NOT NULL DEFAULT '{}'::jsonb,                    -- * Matching criteria: {origins, destinations, originCountries, destinationCountries, carriers, cabins, travelerTypes, tripTypes, sources, channels, minNet, maxNet}; {} = everything.
  calculation         text NOT NULL CHECK (calculation IN ('percentage','fixed','percentage_plus_fixed')), -- * How the markup is computed.
  percentage          numeric(7,4) CHECK (percentage BETWEEN -100 AND 1000), -- Percentage of the net price (5.0000 = 5 %), negative = discount.
  fixed_amount        numeric(12,2),                                         -- Fixed amount added.
  fixed_currency      char(3) CHECK (fixed_currency ~ '^[A-Z]{3}$'),         -- Currency of fixed_amount (converted when the offer currency differs).
  applies_per         text NOT NULL DEFAULT 'traveler' CHECK (applies_per IN ('booking','traveler','segment')), -- Unit the fixed part is applied to.
  min_amount          numeric(12,2),                                         -- Lower cap of the computed markup per unit.
  max_amount          numeric(12,2),                                         -- Upper cap of the computed markup per unit.
  priority            integer NOT NULL DEFAULT 100,                          -- * Evaluation order (lower first); first matching non-stackable rule wins.
  stackable           boolean NOT NULL DEFAULT false,                        -- Whether the rule adds to other matching rules.
  is_default          boolean NOT NULL DEFAULT false,                        -- Seeded catch-all rule.
  is_active           boolean NOT NULL DEFAULT true,                         -- * Enabled flag.
  active_from         timestamptz,                                           -- Start of validity window (NULL = immediately).
  active_until        timestamptz,                                           -- End of validity window (NULL = open-ended).
  created_by_staff_id text,                                                  -- Staff id (stf_, platform.tenant_memberships) by value.
  version             integer NOT NULL DEFAULT 1,                            -- Optimistic-locking counter.
  created_at          timestamptz NOT NULL DEFAULT now(),                    -- Row creation time.
  updated_at          timestamptz NOT NULL DEFAULT now(),                    -- Last modification time.
  CONSTRAINT markup_rules_window_ck CHECK (active_until IS NULL OR active_from IS NULL OR active_until > active_from),
  CONSTRAINT markup_rules_values_ck CHECK ((calculation = 'fixed' AND fixed_amount IS NOT NULL) OR (calculation = 'percentage' AND percentage IS NOT NULL) OR (calculation = 'percentage_plus_fixed' AND percentage IS NOT NULL AND fixed_amount IS NOT NULL))
);
CREATE INDEX markup_rules_active_idx ON markup_rules (priority) WHERE is_active;

-- Fee rules: service, payment-card, ticketing, change and cancellation fees charged by the OTA.
CREATE TABLE fee_rules (
  id                  text PRIMARY KEY CHECK (id LIKE 'fee\_%'),             -- Fee rule id (fee_ + ULID).
  name                text NOT NULL,                                         -- * Internal rule name.
  label               text NOT NULL,                                         -- Label shown to the customer in the price breakdown.
  fee_type            text NOT NULL CHECK (fee_type IN ('booking_service','payment_card','ticketing','change','cancellation','ancillary_service')), -- * What the fee is charged for.
  scope               jsonb NOT NULL DEFAULT '{}'::jsonb,                    -- * Matching criteria (same shape as markup_rules.scope, plus cardBrands for payment_card).
  calculation         text NOT NULL CHECK (calculation IN ('percentage','fixed','percentage_plus_fixed')), -- * How the fee is computed.
  percentage          numeric(7,4) CHECK (percentage BETWEEN 0 AND 100),     -- Percentage of the base amount.
  fixed_amount        numeric(12,2) CHECK (fixed_amount >= 0),               -- Fixed amount.
  currency            char(3) CHECK (currency ~ '^[A-Z]{3}$'),               -- Currency of fixed_amount.
  applies_per         text NOT NULL DEFAULT 'booking' CHECK (applies_per IN ('booking','traveler','segment')), -- Unit the fee is applied to.
  min_amount          numeric(12,2),                                         -- Lower cap.
  max_amount          numeric(12,2),                                         -- Upper cap.
  refundable          boolean NOT NULL DEFAULT false,                        -- Whether the fee is refunded on cancellation.
  priority            integer NOT NULL DEFAULT 100,                          -- * Evaluation order (lower first).
  is_active           boolean NOT NULL DEFAULT true,                         -- * Enabled flag.
  active_from         timestamptz,                                           -- Start of validity window.
  active_until        timestamptz,                                           -- End of validity window.
  created_by_staff_id text,                                                  -- Staff id (stf_) by value.
  version             integer NOT NULL DEFAULT 1,                            -- Optimistic-locking counter.
  created_at          timestamptz NOT NULL DEFAULT now(),                    -- Row creation time.
  updated_at          timestamptz NOT NULL DEFAULT now(),                    -- Last modification time.
  CONSTRAINT fee_rules_window_ck CHECK (active_until IS NULL OR active_from IS NULL OR active_until > active_from)
);
CREATE INDEX fee_rules_active_idx ON fee_rules (fee_type, priority) WHERE is_active;

-- E-mail / SMS templates of the OTA (seeded at provisioning, editable in the console).
CREATE TABLE notification_templates (
  id           text PRIMARY KEY CHECK (id LIKE 'ntt\_%'),                    -- Template id (ntt_ + ULID).
  key          text NOT NULL CHECK (key ~ '^[a-z]+(\.[a-z_]+)+$'),          -- * Event key, e.g. booking.confirmed, booking.ticketed, auth.verify_email, auth.password_reset.
  channel      text NOT NULL CHECK (channel IN ('email','sms')),             -- * Delivery channel.
  locale       text NOT NULL,                                                -- * Locale of the template (BCP 47).
  subject      text,                                                         -- E-mail subject template (required for e-mail).
  body_html    text,                                                         -- HTML body template (e-mail).
  body_text    text NOT NULL,                                                -- Plain-text body template (e-mail fallback / SMS).
  sample_data  jsonb NOT NULL DEFAULT '{}'::jsonb,                           -- Example variables for the console preview.
  is_system    boolean NOT NULL DEFAULT false,                               -- Seeded default (can be reset to the platform version).
  is_active    boolean NOT NULL DEFAULT true,                                -- Disabled templates fall back to the default locale.
  version      integer NOT NULL DEFAULT 1,                                   -- Optimistic-locking counter.
  created_at   timestamptz NOT NULL DEFAULT now(),                           -- Row creation time.
  updated_at   timestamptz NOT NULL DEFAULT now(),                           -- Last modification time.
  CONSTRAINT notification_templates_key_uq UNIQUE (key, channel, locale),
  CONSTRAINT notification_templates_subject_ck CHECK (channel <> 'email' OR subject IS NOT NULL)
);

-- End customers with an account on the OTA's storefront (shared by test and live mode).
CREATE TABLE customers (
  id                  text PRIMARY KEY CHECK (id LIKE 'cus\_%'),             -- Customer id (cus_ + ULID).
  email               text NOT NULL CHECK (position('@' in email) > 1),      -- * Login and contact e-mail (unique case-insensitively). account.delete replaces it with '<HMAC-SHA-256 hex of the address>@deleted.invalid' so the address can register again.
  email_verified_at   timestamptz,                                           -- When the e-mail was verified (NULL = unverified).
  pending_email       text CHECK (position('@' in pending_email) > 1),       -- New e-mail requested via account.update, awaiting auth.verifyEmail (then moved into email; uniqueness re-checked at that moment).
  first_name          text,                                                  -- * Given name.
  last_name           text,                                                  -- * Family name.
  date_of_birth       date,                                                  -- Date of birth of the account holder.
  phone_country_code  text CHECK (phone_country_code ~ '^[0-9]{1,4}$'),      -- Country calling code of the phone (Amadeus countryCallingCode).
  phone_number        text CHECK (phone_number ~ '^[0-9]{1,15}$'),           -- Phone number, digits only.
  status              text NOT NULL DEFAULT 'active' CHECK (status IN ('pending_verification','active','disabled','deleted')), -- * Account state.
  marketing_consent   boolean NOT NULL DEFAULT false,                        -- Current marketing consent (every change is logged in customer_consents).
  marketing_consent_updated_at timestamptz,                                  -- When marketing consent was last given or withdrawn.
  marketing_consent_source text CHECK (marketing_consent_source IN ('sign_up','account','unsubscribe_link','console')), -- Where the last marketing consent change came from.
  terms_accepted_version text,                                               -- Version of the terms accepted at sign-up (storefront legal termsVersion).
  terms_accepted_at   timestamptz,                                           -- When those terms were accepted.
  disabled_reason     text,                                                  -- Why staff disabled the account.
  last_sign_in_at     timestamptz,                                           -- Last successful sign-in (auth.signIn).
  last_booking_at     timestamptz,                                           -- Creation time of the latest booking (denormalised for the console sort and hasBookings filter).
  total_spent_amount  numeric(12,2) NOT NULL DEFAULT 0,                      -- Captured minus refunded selling totals, in storefront_settings.default_currency (denormalised, updated with payments/refunds).
  deleted_at          timestamptz,                                           -- When the account was deleted (PII anonymised by the erasure job, bookings kept).
  metadata            jsonb NOT NULL DEFAULT '{}'::jsonb,                    -- OTA-defined key/values set through the SDK.
  version             integer NOT NULL DEFAULT 1,                            -- Optimistic-locking counter.
  created_at          timestamptz NOT NULL DEFAULT now(),                    -- * Sign-up time.
  updated_at          timestamptz NOT NULL DEFAULT now(),                    -- Last modification time.
  CONSTRAINT customers_deleted_ck CHECK (status <> 'deleted' OR (deleted_at IS NOT NULL AND email LIKE '%@deleted.invalid' AND pending_email IS NULL))
);
-- text_pattern_ops serves both the uniqueness/equality lookup and the console's e-mail prefix search (q).
CREATE UNIQUE INDEX customers_email_lower_uq ON customers (lower(email) text_pattern_ops);
CREATE INDEX customers_pending_email_idx ON customers (lower(pending_email)) WHERE pending_email IS NOT NULL;
CREATE INDEX customers_created_idx ON customers (created_at DESC, id DESC);
CREATE INDEX customers_last_name_idx ON customers (lower(last_name) text_pattern_ops);
CREATE INDEX customers_first_name_idx ON customers (lower(first_name) text_pattern_ops);
CREATE INDEX customers_name_sort_idx ON customers (lower(last_name), lower(first_name), id);
CREATE INDEX customers_last_booking_idx ON customers (last_booking_at DESC NULLS LAST, id DESC);
CREATE INDEX customers_total_spent_idx ON customers (total_spent_amount DESC, id DESC);

-- Append-only consent log per customer (terms and privacy acceptance, marketing opt-in / opt-out): the legal proof
-- behind customers.marketing_consent and customers.terms_accepted_version.
CREATE TABLE customer_consents (
  id             text PRIMARY KEY CHECK (id LIKE 'ccn\_%'),                  -- Consent event id (ccn_ + ULID).
  customer_id    text NOT NULL REFERENCES customers (id) ON DELETE CASCADE,  -- * Customer.
  kind           text NOT NULL CHECK (kind IN ('terms','privacy','marketing')), -- * What the event is about.
  policy_version text,                                                       -- * Terms / privacy policy version (storefront legal versions); NULL for marketing.
  granted        boolean NOT NULL,                                           -- * true = accepted / given, false = withdrawn.
  source         text NOT NULL CHECK (source IN ('sign_up','account','unsubscribe_link','console')), -- * Where the change came from.
  staff_id       text CHECK (staff_id LIKE 'stf\_%'),                        -- Staff id (stf_) by value when source = console.
  ip_hash        text CHECK (ip_hash ~ '^[0-9a-f]{64}$'),                    -- HMAC-SHA-256 (tenant pepper) of the client IP: proof without keeping the IP.
  created_at     timestamptz NOT NULL DEFAULT now(),                         -- * Event time.
  updated_at     timestamptz NOT NULL DEFAULT now(),                         -- Equal to created_at (append-only).
  CONSTRAINT customer_consents_version_ck CHECK (kind = 'marketing' OR policy_version IS NOT NULL)
);
CREATE INDEX customer_consents_customer_idx ON customer_consents (customer_id, kind, created_at DESC);

-- Login methods of a customer: password (Argon2id hash) or social identity, with e-mail verification state.
CREATE TABLE customer_identities (
  id                         text PRIMARY KEY CHECK (id LIKE 'cid\_%'),      -- Identity id (cid_ + ULID).
  customer_id                text NOT NULL REFERENCES customers (id) ON DELETE CASCADE, -- * Customer.
  provider                   text NOT NULL CHECK (provider IN ('password','google','apple','facebook','magic_link')), -- * Login method.
  provider_subject           text NOT NULL,                                  -- * Subject at the provider (lower-cased e-mail for password, OIDC sub otherwise); rewritten when a pending e-mail is verified and replaced by the deleted-account placeholder at account.delete.
  password_hash              text,                                           -- Argon2id hash (password provider only).
  password_updated_at        timestamptz,                                    -- Last password change (sessions issued before are revoked).
  email                      text,                                           -- E-mail asserted by this identity.
  email_verified_at          timestamptz,                                    -- When the e-mail of this identity was verified.
  verification_token_hash    text UNIQUE,                                    -- SHA-256 of the pending e-mail verification token (sign-up address or customers.pending_email).
  verification_sent_at       timestamptz,                                    -- When the verification e-mail was sent (resend throttling).
  verification_expires_at    timestamptz,                                    -- Verification token expiry.
  failed_attempts            integer NOT NULL DEFAULT 0 CHECK (failed_attempts >= 0), -- Consecutive failed password attempts.
  locked_until               timestamptz,                                    -- Temporary lockout end.
  last_used_at               timestamptz,                                    -- Last successful sign-in with this identity.
  disabled_at                timestamptz,                                    -- * When the identity was disabled (account.delete, staff); a disabled identity cannot sign in and frees its subject.
  created_at                 timestamptz NOT NULL DEFAULT now(),             -- Row creation time.
  updated_at                 timestamptz NOT NULL DEFAULT now(),             -- Last modification time.
  CONSTRAINT customer_identities_customer_provider_uq UNIQUE (customer_id, provider),
  CONSTRAINT customer_identities_password_ck CHECK (provider <> 'password' OR password_hash IS NOT NULL)
);
-- A subject is unique among enabled identities only, so a deleted account's address can sign up again.
CREATE UNIQUE INDEX customer_identities_subject_uq ON customer_identities (provider, provider_subject) WHERE disabled_at IS NULL;

-- Customer refresh tokens (rotating; 30 days with remember_me, 12 hours without). One row per token generation;
-- family_id groups a sign-in and family_expires_at is the absolute lifetime of the family.
CREATE TABLE customer_sessions (
  id                 text PRIMARY KEY CHECK (id LIKE 'ses\_%'),               -- Session id (ses_ + ULID), also carried as sid in the access token.
  customer_id        text NOT NULL REFERENCES customers (id) ON DELETE CASCADE, -- * Customer.
  identity_id        text REFERENCES customer_identities (id) ON DELETE SET NULL, -- Identity used to sign in.
  refresh_token_hash text NOT NULL UNIQUE,                                   -- * SHA-256 of the opaque refresh token.
  family_id          text NOT NULL,                                          -- * Rotation family; presenting an already rotated token revokes the whole family.
  replaced_by_id     text REFERENCES customer_sessions (id) ON DELETE SET NULL, -- Token that replaced this one at rotation.
  remember_me        boolean NOT NULL DEFAULT false,                         -- * rememberMe at sign-in (copied on rotation): 30-day instead of 12-hour family lifetime.
  family_expires_at  timestamptz NOT NULL,                                   -- * Absolute end of the family (sign-in + 30 d or 12 h); rotation never extends it.
  user_agent         text,                                                   -- Client user agent.
  ip_address         inet,                                                   -- Client IP at issue time.
  ip_country         char(2) CHECK (ip_country ~ '^[A-Z]{2}$'),              -- Country of the client IP (GeoIP) for the session list and anomaly checks.
  expires_at         timestamptz NOT NULL,                                   -- * Refresh token expiry (never after family_expires_at).
  last_used_at       timestamptz,                                            -- Last use of the token.
  rotated_at         timestamptz,                                            -- When it was exchanged for a new token.
  revoked_at         timestamptz,                                            -- When it was revoked.
  revoke_reason      text CHECK (revoke_reason IN ('logout','rotation_reuse','password_change','admin','expired','account_deleted')), -- Why it was revoked.
  created_at         timestamptz NOT NULL DEFAULT now(),                     -- Issue time.
  updated_at         timestamptz NOT NULL DEFAULT now(),                     -- Last modification time.
  CONSTRAINT customer_sessions_family_expiry_ck CHECK (expires_at <= family_expires_at)
);
CREATE INDEX customer_sessions_customer_idx ON customer_sessions (customer_id) WHERE revoked_at IS NULL AND rotated_at IS NULL;
CREATE INDEX customer_sessions_family_idx ON customer_sessions (family_id);
CREATE INDEX customer_sessions_expires_idx ON customer_sessions (expires_at);
CREATE INDEX customer_sessions_identity_idx ON customer_sessions (identity_id) WHERE identity_id IS NOT NULL;
CREATE INDEX customer_sessions_replaced_by_idx ON customer_sessions (replaced_by_id) WHERE replaced_by_id IS NOT NULL;

-- Password reset requests (single-use, short-lived tokens sent by e-mail).
CREATE TABLE customer_password_resets (
  id           text PRIMARY KEY CHECK (id LIKE 'pwr\_%'),                    -- Reset id (pwr_ + ULID).
  customer_id  text NOT NULL REFERENCES customers (id) ON DELETE CASCADE,    -- * Customer.
  token_hash   text NOT NULL UNIQUE,                                         -- SHA-256 of the reset token.
  requested_ip inet,                                                         -- IP that requested the reset.
  expires_at   timestamptz NOT NULL,                                         -- * Token expiry (e.g. 1 hour).
  used_at      timestamptz,                                                  -- When the token was consumed.
  created_at   timestamptz NOT NULL DEFAULT now(),                           -- Request time.
  updated_at   timestamptz NOT NULL DEFAULT now()                            -- Last modification time.
);
CREATE INDEX customer_password_resets_customer_idx ON customer_password_resets (customer_id, created_at DESC);
CREATE INDEX customer_password_resets_expires_idx ON customer_password_resets (expires_at);

-- Customer preferences (one row per customer).
CREATE TABLE customer_preferences (
  id                    text PRIMARY KEY CHECK (id LIKE 'cpf\_%'),           -- Preferences id (cpf_ + ULID).
  customer_id           text NOT NULL UNIQUE REFERENCES customers (id) ON DELETE CASCADE, -- * Customer (one-to-one).
  locale                text,                                                -- Preferred locale.
  currency              char(3) CHECK (currency ~ '^[A-Z]{3}$'),             -- Preferred selling currency.
  home_airport          char(3) CHECK (home_airport ~ '^[A-Z]{3}$'),         -- Default origin (IATA, by value).
  cabin                 text CHECK (cabin IN ('ECONOMY','PREMIUM_ECONOMY','BUSINESS','FIRST')), -- Preferred cabin (Amadeus TravelClass).
  seat_preference       text CHECK (seat_preference IN ('AISLE','WINDOW','NO_PREFERENCE')), -- Preferred seat position.
  meal_preference       text CHECK (meal_preference ~ '^[A-Z]{4}$'),         -- Special meal SSR code, e.g. VGML.
  preferred_carriers    text[] NOT NULL DEFAULT '{}',                        -- Carriers to favour (includedAirlineCodes).
  excluded_carriers     text[] NOT NULL DEFAULT '{}',                        -- Carriers to avoid (excludedAirlineCodes).
  non_stop_only         boolean NOT NULL DEFAULT false,                      -- Default nonStop search flag.
  notification_settings jsonb NOT NULL DEFAULT '{}'::jsonb,                  -- Channel opt-ins, e.g. {"smsBookingUpdates":true}.
  version               integer NOT NULL DEFAULT 1,                          -- Optimistic-locking counter.
  created_at            timestamptz NOT NULL DEFAULT now(),                  -- Row creation time.
  updated_at            timestamptz NOT NULL DEFAULT now()                   -- Last modification time.
);

-- GDPR data-access / portability export jobs of a customer (account.dataExports.*, account.delete with exportData).
-- Status machine: queued -> processing -> ready -> expired ; queued | processing -> failed.
CREATE TABLE customer_data_exports (
  id               text PRIMARY KEY CHECK (id LIKE 'dex\_%'),                -- Export id (dex_ + ULID).
  customer_id      text NOT NULL REFERENCES customers (id) ON DELETE CASCADE, -- * Customer whose data is exported.
  status           text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','processing','ready','failed','expired')), -- * Job state.
  format           text NOT NULL DEFAULT 'json' CHECK (format IN ('json','csv')), -- * File format inside the ZIP.
  include_bookings boolean NOT NULL DEFAULT true,                            -- Bookings, travellers, tickets and payment summaries are included.
  requested_via    text NOT NULL DEFAULT 'account' CHECK (requested_via IN ('account','account_deletion')), -- account.dataExports.create or account.delete (exportData = true).
  delivery_email   text,                                                     -- Address the ready e-mail goes to, captured at request time (account.delete hashes customers.email); cleared at expiry.
  storage_key      text UNIQUE,                                              -- * Object-storage key of the ZIP (tenant prefix, SSE-KMS); NULL until ready, file deleted at expiry.
  size_bytes       bigint CHECK (size_bytes >= 0),                           -- ZIP size.
  content_hash     text CHECK (content_hash ~ '^[0-9a-f]{64}$'),             -- SHA-256 of the ZIP.
  error            text,                                                     -- Failure reason (status failed).
  attempts         integer NOT NULL DEFAULT 0 CHECK (attempts >= 0),         -- Worker attempts.
  started_at       timestamptz,                                              -- When a worker started the job.
  ready_at         timestamptz,                                              -- When the file became available.
  expires_at       timestamptz,                                              -- * When the file is deleted (ready_at + 7 days).
  version          integer NOT NULL DEFAULT 1,                               -- Optimistic-locking counter (worker state changes).
  created_at       timestamptz NOT NULL DEFAULT now(),                       -- * Request time (requestedAt).
  updated_at       timestamptz NOT NULL DEFAULT now(),                       -- Last modification time.
  CONSTRAINT customer_data_exports_ready_ck CHECK (status <> 'ready' OR (storage_key IS NOT NULL AND ready_at IS NOT NULL AND expires_at IS NOT NULL))
);
CREATE INDEX customer_data_exports_customer_idx ON customer_data_exports (customer_id, created_at DESC);
CREATE UNIQUE INDEX customer_data_exports_active_uq ON customer_data_exports (customer_id) WHERE status IN ('queued','processing');
CREATE INDEX customer_data_exports_queue_idx ON customer_data_exports (created_at) WHERE status = 'queued';
CREATE INDEX customer_data_exports_expires_idx ON customer_data_exports (expires_at) WHERE status = 'ready';

-- Travellers saved in a customer's profile (self, family, colleagues) for fast checkout.
CREATE TABLE saved_travelers (
  id                              text PRIMARY KEY CHECK (id LIKE 'trv\_%'), -- Saved traveller id (trv_ + ULID).
  customer_id                     text NOT NULL REFERENCES customers (id) ON DELETE CASCADE, -- * Owning customer.
  label                           text,                                      -- Nickname shown in the picker, e.g. "Me", "Anna".
  is_self                         boolean NOT NULL DEFAULT false,            -- The account holder (at most one per customer).
  first_name                      text NOT NULL,                             -- * Given name as on the travel document (Amadeus name.firstName).
  middle_name                     text,                                      -- Middle name(s).
  last_name                       text NOT NULL,                             -- * Family name (Amadeus name.lastName).
  second_last_name                text,                                      -- Second family name.
  date_of_birth                   date,                                      -- * Date of birth (drives the traveler type).
  gender                          text CHECK (gender IN ('MALE','FEMALE','UNSPECIFIED','UNDISCLOSED')), -- Amadeus StakeholderGender.
  email                           text,                                      -- Traveller e-mail (Amadeus contact.emailAddress).
  phone_country_code              text CHECK (phone_country_code ~ '^[0-9]{1,4}$'), -- Phone country calling code.
  phone_number                    text CHECK (phone_number ~ '^[0-9]{1,15}$'), -- Phone number, digits only.
  loyalty_programs                jsonb NOT NULL DEFAULT '[]'::jsonb,        -- Amadeus loyaltyPrograms [{programOwner, id}].
  emergency_contact               jsonb,                                     -- Amadeus emergencyContact {addresseeName, countryCode, number, text}.
  discount_eligibility_ciphertext bytea,                                     -- Encrypted Amadeus discountEligibility (resident card / certificate numbers).
  encryption_key_id               text,                                      -- KMS key id wrapping the data key of the ciphertext.
  last_used_at                    timestamptz,                               -- Last time the traveller was used in a booking (SavedTraveler.lastUsedAt).
  version                         integer NOT NULL DEFAULT 1,                -- Optimistic-locking counter.
  created_at                      timestamptz NOT NULL DEFAULT now(),        -- Row creation time.
  updated_at                      timestamptz NOT NULL DEFAULT now()         -- Last modification time.
);
CREATE INDEX saved_travelers_customer_idx ON saved_travelers (customer_id, lower(last_name));
CREATE UNIQUE INDEX saved_travelers_self_uq ON saved_travelers (customer_id) WHERE is_self;

-- Identity documents of saved travellers (Amadeus IdentityDocument); the number is encrypted by the application.
CREATE TABLE saved_traveler_documents (
  id                 text PRIMARY KEY CHECK (id LIKE 'tdc\_%'),               -- Document id (tdc_ + ULID).
  saved_traveler_id  text NOT NULL REFERENCES saved_travelers (id) ON DELETE CASCADE, -- * Saved traveller.
  document_type      text NOT NULL CHECK (document_type IN ('VISA','PASSPORT','IDENTITY_CARD','KNOWN_TRAVELER','REDRESS')), -- * Amadeus documentType.
  number_ciphertext  bytea NOT NULL,                                         -- AES-256-GCM ciphertext of the document number.
  details_ciphertext bytea,                                                  -- Ciphertext of the remaining sensitive fields (birthPlace, issuanceLocation).
  encryption_key_id  text NOT NULL,                                          -- KMS key id wrapping the data key.
  number_last4       text NOT NULL CHECK (length(number_last4) BETWEEN 1 AND 4), -- * Last 4 characters of the number (display).
  issuance_date      date,                                                   -- Issue date.
  expiry_date        date,                                                   -- * Expiry date (validity checks and reminders).
  issuance_country   char(2) CHECK (issuance_country ~ '^[A-Z]{2}$'),        -- * Issuing country (ISO 3166-1 alpha-2).
  nationality        char(2) CHECK (nationality ~ '^[A-Z]{2}$'),             -- Nationality on the document.
  validity_country   char(2) CHECK (validity_country ~ '^[A-Z]{2}$'),        -- Country where the document (e.g. visa) is valid.
  birth_country      char(2) CHECK (birth_country ~ '^[A-Z]{2}$'),           -- Country of birth.
  holder             boolean NOT NULL DEFAULT true,                          -- The traveller is the holder of the document.
  is_primary         boolean NOT NULL DEFAULT false,                         -- Default document used at checkout.
  version            integer NOT NULL DEFAULT 1,                             -- Optimistic-locking counter.
  created_at         timestamptz NOT NULL DEFAULT now(),                     -- Row creation time.
  updated_at         timestamptz NOT NULL DEFAULT now()                      -- Last modification time.
);
CREATE INDEX saved_traveler_documents_traveler_idx ON saved_traveler_documents (saved_traveler_id);
CREATE UNIQUE INDEX saved_traveler_documents_primary_uq ON saved_traveler_documents (saved_traveler_id) WHERE is_primary;
CREATE INDEX saved_traveler_documents_expiry_idx ON saved_traveler_documents (expiry_date);

-- Flight searches (Flight Offers Search GET/POST, or Flight Availabilities Search in the console) with criteria and TTL.
CREATE TABLE flight_searches (
  id               text PRIMARY KEY CHECK (id LIKE 'srch\_%'),               -- Search id (srch_ + ULID).
  environment      text NOT NULL CHECK (environment IN ('test','live')),     -- * Amadeus environment used (from the API key).
  kind             text NOT NULL DEFAULT 'offers' CHECK (kind IN ('offers','availability')), -- * offers = FlightOffersSearch, availability = FlightAvailabilitiesSearch.
  mode             text NOT NULL DEFAULT 'simple' CHECK (mode IN ('simple','advanced')), -- * simple = Velexis criteria (GET-style), advanced = full Amadeus POST body.
  channel          text NOT NULL DEFAULT 'storefront' CHECK (channel IN ('storefront','console')), -- Which surface ran the search.
  customer_id      text REFERENCES customers (id) ON DELETE SET NULL,        -- Signed-in customer (NULL = anonymous or staff).
  staff_id         text,                                                     -- Staff id (stf_) by value for console searches.
  criteria         jsonb NOT NULL,                                           -- * Normalised Velexis search criteria as received.
  amadeus_request  jsonb NOT NULL,                                           -- Exact Amadeus query/body sent (GetFlightOffersQuery or availability query).
  origin_iata      char(3),                                                  -- First origin (IATA, by value) for listing/analytics.
  destination_iata char(3),                                                  -- First destination (IATA, by value).
  departure_date   date,                                                     -- First departure date.
  return_date      date,                                                     -- Return date for round trips.
  adults           smallint NOT NULL DEFAULT 1 CHECK (adults BETWEEN 0 AND 9), -- Number of adult travellers.
  children         smallint NOT NULL DEFAULT 0 CHECK (children BETWEEN 0 AND 9), -- Number of child travellers.
  infants          smallint NOT NULL DEFAULT 0 CHECK (infants BETWEEN 0 AND 9), -- Number of infants.
  cabin            text CHECK (cabin IN ('ECONOMY','PREMIUM_ECONOMY','BUSINESS','FIRST')), -- Requested cabin.
  currency         char(3) CHECK (currency ~ '^[A-Z]{3}$'),                  -- Requested currency (currencyCode).
  status           text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','completed','failed')), -- * Search state.
  result_count     integer NOT NULL DEFAULT 0 CHECK (result_count >= 0),     -- * Offers (or availability options) returned.
  dictionaries     jsonb,                                                    -- Amadeus dictionaries of the response (locations, carriers, aircraft, currencies).
  warnings         jsonb,                                                    -- Amadeus warnings of the response.
  facets           jsonb,                                                    -- Unfiltered result facets computed when the search ran (flights.getSearch).
  highlights       jsonb,                                                    -- Cheapest / fastest / best offer ids and prices.
  one_way_combinations jsonb,                                                -- Amadeus meta.oneWayCombinations translated to off_ ids (addOneWayOffers).
  availability_data jsonb,                                                   -- Verbatim availability results (kind = availability only).
  error_code       text,                                                     -- Public error code when failed.
  duration_ms      integer,                                                  -- Supplier latency.
  expires_at       timestamptz NOT NULL,                                     -- * When the cached results expire (SEARCH_EXPIRED afterwards).
  created_at       timestamptz NOT NULL DEFAULT now(),                       -- * Search time.
  updated_at       timestamptz NOT NULL DEFAULT now()                        -- Last modification time.
);
CREATE INDEX flight_searches_created_idx ON flight_searches (environment, created_at DESC);
CREATE INDEX flight_searches_customer_idx ON flight_searches (customer_id, created_at DESC) WHERE customer_id IS NOT NULL;
CREATE INDEX flight_searches_expires_idx ON flight_searches (expires_at);
CREATE INDEX flight_searches_route_idx ON flight_searches (origin_iata, destination_iata, departure_date);

-- Cached Amadeus flight offers returned to clients as off_ ids (search results, upsell results, raw console offers).
-- The normalised summary columns are filled at insert and back every flights.listResults filter and sort in SQL.
-- A search holds at most 250 offers (maxFlightOffers), so filters and sorts run over the rows found by search_id.
CREATE TABLE flight_offers (
  id                      text PRIMARY KEY CHECK (id LIKE 'off\_%'),         -- Offer id (off_ + ULID).
  environment             text NOT NULL CHECK (environment IN ('test','live')), -- Amadeus environment of the offer.
  origin                  text NOT NULL DEFAULT 'search' CHECK (origin IN ('search','upsell','raw')), -- * How the offer entered the cache.
  search_id               text REFERENCES flight_searches (id) ON DELETE CASCADE, -- * Search that returned it.
  upsell_id               text,                                              -- Upsell call that returned it (FK added below, circular with offer_upsells).
  amadeus_offer_id        text NOT NULL,                                     -- * Amadeus flight-offer id within its response, e.g. "1".
  source                  text NOT NULL DEFAULT 'GDS' CHECK (source IN ('GDS','LTC','PYTON','EAC','NDC')), -- Amadeus FlightOfferSource.
  position                integer,                                           -- Rank in the supplier response.
  payload                 jsonb NOT NULL,                                    -- * Verbatim AmadeusFlightOffer (net prices).
  currency                char(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'), -- Price currency.
  net_total               numeric(12,2) NOT NULL CHECK (net_total >= 0),     -- * Amadeus price.grandTotal (net).
  markup_amount           numeric(12,2) NOT NULL DEFAULT 0,                  -- * Markup applied by markup_rules.
  selling_total           numeric(12,2) NOT NULL,                            -- * Price shown to the customer (net + markup).
  markup_rule_id          text REFERENCES markup_rules (id) ON DELETE SET NULL, -- Rule that produced the markup.
  validating_carrier      text CHECK (validating_carrier ~ '^[A-Z0-9]{2}$'), -- * First validatingAirlineCodes entry.
  marketing_carriers      text[] NOT NULL DEFAULT '{}',                      -- * Marketing carriers of all segments (carriers filter: contained in the requested list; facets).
  origin_iata             char(3),                                           -- First departure airport.
  destination_iata        char(3),                                           -- Destination of the first itinerary.
  first_departure_local   timestamp NOT NULL,                                -- * First segment departure (local time, as Amadeus gives it; departure sort).
  last_arrival_local      timestamp,                                         -- Last segment arrival (local time; arrival sort).
  itinerary_departure_minutes smallint[] NOT NULL DEFAULT '{}',              -- Per itinerary: local departure time as minutes after midnight (departureWindow filter, index 0 = first itinerary).
  itinerary_arrival_minutes   smallint[] NOT NULL DEFAULT '{}',              -- Per itinerary: local arrival time as minutes after midnight (arrivalWindow filter).
  itinerary_duration_minutes  integer[] NOT NULL DEFAULT '{}',               -- Per itinerary: duration in minutes (maxDurationMinutes: every element at most the limit).
  max_stops               smallint NOT NULL DEFAULT 0,                       -- Highest number of stops over the itineraries (stops filter).
  total_duration_minutes  integer,                                           -- Sum of itinerary durations (duration sort).
  main_cabin              text CHECK (main_cabin IN ('ECONOMY','PREMIUM_ECONOMY','BUSINESS','FIRST')), -- Cabin of the longest segment (cabins filter).
  min_checked_bags        smallint CHECK (min_checked_bags >= 0),            -- Fewest included checked bags per adult over all segments (minIncludedCheckedBags); NULL = unknown.
  refundable              boolean,                                           -- Refundable per fare rules / branded-fare amenities; NULL = unknown (excluded when the filter is set).
  changeable              boolean,                                           -- Changeable per fare rules / branded-fare amenities; NULL = unknown.
  branded_fares           text[] NOT NULL DEFAULT '{}',                      -- Branded fare codes on any itinerary (brandedFares filter: overlaps the requested list).
  best_score              numeric(12,4),                                     -- Ranking value of the default "best" sort (price, duration and stops weighted at insert; lower is better).
  bookable_seats          smallint CHECK (bookable_seats BETWEEN 1 AND 9),   -- numberOfBookableSeats.
  last_ticketing_date     date,                                              -- lastTicketingDate of the offer.
  instant_ticketing_required boolean NOT NULL DEFAULT false,                 -- instantTicketingRequired flag.
  expires_at              timestamptz NOT NULL,                              -- * Cache expiry (OFFER_EXPIRED afterwards; purge job).
  created_at              timestamptz NOT NULL DEFAULT now(),                -- Row creation time.
  updated_at              timestamptz NOT NULL DEFAULT now(),                -- Last modification time.
  CONSTRAINT flight_offers_selling_ck CHECK (selling_total = net_total + markup_amount),
  CONSTRAINT flight_offers_origin_ck CHECK ((origin <> 'search' OR search_id IS NOT NULL) AND (origin <> 'upsell' OR upsell_id IS NOT NULL)),
  CONSTRAINT flight_offers_itinerary_ck CHECK (cardinality(itinerary_departure_minutes) = cardinality(itinerary_arrival_minutes)
    AND cardinality(itinerary_departure_minutes) = cardinality(itinerary_duration_minutes)
    AND 0 <= ALL (itinerary_departure_minutes) AND 1439 >= ALL (itinerary_departure_minutes)
    AND 0 <= ALL (itinerary_arrival_minutes) AND 1439 >= ALL (itinerary_arrival_minutes))
);
CREATE UNIQUE INDEX flight_offers_search_offer_uq ON flight_offers (search_id, amadeus_offer_id) WHERE origin = 'search';
CREATE UNIQUE INDEX flight_offers_upsell_offer_uq ON flight_offers (upsell_id, amadeus_offer_id) WHERE origin = 'upsell';
CREATE INDEX flight_offers_search_price_idx ON flight_offers (search_id, selling_total, id);
CREATE INDEX flight_offers_search_best_idx ON flight_offers (search_id, best_score, id);
CREATE INDEX flight_offers_expires_idx ON flight_offers (expires_at);
CREATE INDEX flight_offers_markup_rule_idx ON flight_offers (markup_rule_id) WHERE markup_rule_id IS NOT NULL;

-- Branded Fares Upsell calls for a base offer; the branded alternatives are stored as flight_offers (origin = upsell).
CREATE TABLE offer_upsells (
  id              text PRIMARY KEY CHECK (id LIKE 'ups\_%'),                 -- Upsell id (ups_ + ULID).
  base_offer_id   text NOT NULL REFERENCES flight_offers (id) ON DELETE CASCADE, -- * Offer that was upsold.
  amadeus_request jsonb NOT NULL,                                            -- Verbatim upselling request (flightOffers, payments).
  warnings        jsonb,                                                     -- Amadeus warnings.
  dictionaries    jsonb,                                                     -- Amadeus dictionaries of the response.
  status          text NOT NULL DEFAULT 'completed' CHECK (status IN ('completed','no_upsell','failed')), -- * Outcome.
  result_count    integer NOT NULL DEFAULT 0 CHECK (result_count >= 0),      -- * Branded alternatives returned.
  expires_at      timestamptz NOT NULL,                                      -- * Expiry of the upsell results.
  created_at      timestamptz NOT NULL DEFAULT now(),                        -- Row creation time.
  updated_at      timestamptz NOT NULL DEFAULT now()                         -- Last modification time.
);
CREATE INDEX offer_upsells_base_offer_idx ON offer_upsells (base_offer_id);
CREATE INDEX offer_upsells_expires_idx ON offer_upsells (expires_at);
ALTER TABLE flight_offers ADD CONSTRAINT flight_offers_upsell_fk FOREIGN KEY (upsell_id) REFERENCES offer_upsells (id) ON DELETE CASCADE;
CREATE INDEX flight_offers_upsell_idx ON flight_offers (upsell_id) WHERE upsell_id IS NOT NULL;

-- Flight Offers Price results (confirmed price, taxes, bags, other services, credit-card fees, fare rules, booking requirements).
CREATE TABLE priced_offers (
  id                          text PRIMARY KEY CHECK (id LIKE 'prc\_%'),     -- Priced offer id (prc_ + ULID).
  environment                 text NOT NULL CHECK (environment IN ('test','live')), -- * Amadeus environment.
  offer_id                    text NOT NULL REFERENCES flight_offers (id) ON DELETE CASCADE, -- * Main (first) offer that was priced.
  parent_priced_offer_id      text REFERENCES priced_offers (id) ON DELETE SET NULL, -- * Base priced offer this one re-prices with ancillaries (checkout.setAncillaries); NULL for a base pricing.
  offer_ids                   text[] NOT NULL CHECK (cardinality(offer_ids) BETWEEN 1 AND 6), -- All off_ ids priced together (Amadeus allows up to 6).
  include_credit_card_fees    boolean NOT NULL DEFAULT false,                -- include=credit-card-fees was requested.
  include_bags                boolean NOT NULL DEFAULT false,                -- include=bags was requested.
  include_other_services      boolean NOT NULL DEFAULT false,                -- include=other-services was requested.
  include_detailed_fare_rules boolean NOT NULL DEFAULT false,                -- include=detailed-fare-rules was requested.
  force_class                 boolean NOT NULL DEFAULT false,                -- forceClass query flag.
  amadeus_request             jsonb NOT NULL,                                -- Pricing request body (travelers redacted, payments brand/BIN only).
  response                    jsonb NOT NULL,                                -- * Verbatim pricing response: data.flightOffers, bookingRequirements, included{credit-card-fees,bags,other-services,detailed-fare-rules}, dictionaries, warnings.
  booking_requirements        jsonb,                                         -- Extracted bookingRequirements (drives the traveller/contact form).
  price_changed               boolean NOT NULL DEFAULT false,                -- True when the priced total differs from the offer.
  currency                    char(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'), -- Price currency.
  net_total                   numeric(12,2) NOT NULL CHECK (net_total >= 0), -- * Priced Amadeus grandTotal (net).
  taxes_total                 numeric(12,2) NOT NULL DEFAULT 0,              -- Sum of taxes.
  markup_amount               numeric(12,2) NOT NULL DEFAULT 0,              -- Markup applied.
  fee_amount                  numeric(12,2) NOT NULL DEFAULT 0,              -- OTA fees from fee_rules (service/ticketing).
  selling_total               numeric(12,2) NOT NULL,                        -- * Total to pay before ancillaries (net + markup + fees).
  markup_rule_id              text REFERENCES markup_rules (id) ON DELETE SET NULL, -- Markup rule applied.
  last_ticketing_date         date,                                          -- lastTicketingDate of the priced offer.
  expires_at                  timestamptz NOT NULL,                          -- * Expiry (OFFER_EXPIRED; re-price afterwards).
  created_at                  timestamptz NOT NULL DEFAULT now(),            -- Row creation time.
  updated_at                  timestamptz NOT NULL DEFAULT now(),            -- Last modification time.
  CONSTRAINT priced_offers_selling_ck CHECK (selling_total = net_total + markup_amount + fee_amount)
);
CREATE INDEX priced_offers_offer_idx ON priced_offers (offer_id);
CREATE INDEX priced_offers_parent_idx ON priced_offers (parent_priced_offer_id) WHERE parent_priced_offer_id IS NOT NULL;
CREATE INDEX priced_offers_expires_idx ON priced_offers (expires_at);
CREATE INDEX priced_offers_markup_rule_idx ON priced_offers (markup_rule_id) WHERE markup_rule_id IS NOT NULL;

-- Checkout sessions: travellers, contacts, ancillaries and payment for one priced offer (customer or guest).
-- Status machine: open -> payment_pending -> completed | expired | abandoned  (open -> expired | abandoned too).
CREATE TABLE checkouts (
  id                  text PRIMARY KEY CHECK (id LIKE 'chk\_%'),             -- Checkout id (chk_ + ULID).
  environment         text NOT NULL CHECK (environment IN ('test','live')),  -- * Environment (must match the priced offer).
  channel             text NOT NULL DEFAULT 'storefront' CHECK (channel IN ('storefront','console')), -- Storefront self-service or staff-assisted.
  customer_id         text REFERENCES customers (id) ON DELETE SET NULL,     -- * Customer (NULL = guest checkout).
  is_guest            boolean NOT NULL DEFAULT false,                        -- * Started as a guest (kept even if the customer is later erased).
  created_by_staff_id text,                                                  -- Staff id (stf_) by value for console checkouts.
  base_priced_offer_id text NOT NULL REFERENCES priced_offers (id) ON DELETE RESTRICT, -- * Priced offer the checkout was opened with, without ancillaries (ancillary catalogue of setAncillaries).
  priced_offer_id     text NOT NULL REFERENCES priced_offers (id) ON DELETE RESTRICT, -- * Priced offer being bought now (= base, or the ancillary / re-price child); kept while the checkout exists.
  status              text NOT NULL DEFAULT 'open' CHECK (status IN ('open','payment_pending','completed','expired','abandoned')), -- * Checkout state.
  currency            char(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),      -- Currency of all amounts.
  offer_amount        numeric(12,2) NOT NULL,                                -- Selling total of the priced offer.
  ancillaries_amount  numeric(12,2) NOT NULL DEFAULT 0,                      -- Selling total of selected ancillaries.
  fees_amount         numeric(12,2) NOT NULL DEFAULT 0,                      -- Payment / service fees (e.g. credit-card fee for the chosen brand).
  total_amount        numeric(12,2) NOT NULL,                                -- * Amount to pay.
  payment_brand       text,                                                  -- Chosen card brand (Amadeus PaymentBrand) used for credit-card fees.
  locale              text,                                                  -- Locale for confirmations.
  terms_accepted_at   timestamptz,                                           -- When the customer accepted terms and fare rules.
  ip_address          inet,                                                  -- Client IP (fraud screening).
  metadata            jsonb NOT NULL DEFAULT '{}'::jsonb,                    -- OTA-defined key/values.
  expires_at          timestamptz NOT NULL,                                  -- * Expiry (CHECKOUT_EXPIRED; expiry job).
  completed_at        timestamptz,                                           -- When the booking was created.
  version             integer NOT NULL DEFAULT 1,                            -- Optimistic-locking counter (also bumped by child changes).
  created_at          timestamptz NOT NULL DEFAULT now(),                    -- * Start time.
  updated_at          timestamptz NOT NULL DEFAULT now(),                    -- Last modification time.
  CONSTRAINT checkouts_total_ck CHECK (total_amount = offer_amount + ancillaries_amount + fees_amount),
  CONSTRAINT checkouts_guest_ck CHECK (NOT (is_guest AND customer_id IS NOT NULL))
);
CREATE INDEX checkouts_customer_idx ON checkouts (customer_id, created_at DESC) WHERE customer_id IS NOT NULL;
CREATE INDEX checkouts_expiry_idx ON checkouts (expires_at) WHERE status IN ('open','payment_pending');
CREATE INDEX checkouts_priced_offer_idx ON checkouts (priced_offer_id);
CREATE INDEX checkouts_base_priced_offer_idx ON checkouts (base_priced_offer_id);
CREATE INDEX checkouts_created_idx ON checkouts (environment, created_at DESC);

-- Travellers entered in a checkout (become Amadeus travelers at create-order).
CREATE TABLE checkout_travelers (
  id                    text PRIMARY KEY CHECK (id LIKE 'ctr\_%'),           -- Checkout traveller id (ctr_ + ULID).
  checkout_id           text NOT NULL REFERENCES checkouts (id) ON DELETE CASCADE, -- * Checkout.
  saved_traveler_id     text REFERENCES saved_travelers (id) ON DELETE SET NULL, -- Saved traveller it was prefilled from.
  amadeus_traveler_id   text NOT NULL,                                       -- * travelerId of the priced offer travelerPricings ("1", "2" ...).
  traveler_type         text NOT NULL CHECK (traveler_type IN ('ADULT','CHILD','SENIOR','YOUNG','HELD_INFANT','SEATED_INFANT','STUDENT')), -- * Amadeus TravelerType.
  associated_adult_id   text,                                                -- Adult travelerId carrying a HELD_INFANT.
  first_name            text,                                                -- * Given name.
  middle_name           text,                                                -- Middle name(s).
  last_name             text,                                                -- * Family name.
  second_last_name      text,                                                -- Second family name.
  date_of_birth         date,                                                -- Date of birth.
  gender                text CHECK (gender IN ('MALE','FEMALE','UNSPECIFIED','UNDISCLOSED')), -- Amadeus StakeholderGender.
  contact               jsonb,                                               -- Amadeus traveler contact {emailAddress, phones[], address, language, purpose}.
  documents_ciphertext  bytea,                                               -- Encrypted Amadeus documents[] (identity documents incl. numbers).
  discount_eligibility_ciphertext bytea,                                     -- Encrypted Amadeus discountEligibility[] (subType, cityName, travelerType, cardNumber, certificateNumber).
  encryption_key_id     text,                                                -- KMS key id wrapping the row's data key (documents and discount ciphertexts).
  loyalty_programs      jsonb NOT NULL DEFAULT '[]'::jsonb,                  -- Amadeus loyaltyPrograms.
  emergency_contact     jsonb,                                               -- Amadeus emergencyContact.
  save_to_profile       boolean NOT NULL DEFAULT false,                      -- Save as saved traveller after booking.
  position              smallint NOT NULL DEFAULT 0,                         -- Display order.
  created_at            timestamptz NOT NULL DEFAULT now(),                  -- Row creation time.
  updated_at            timestamptz NOT NULL DEFAULT now(),                  -- Last modification time.
  CONSTRAINT checkout_travelers_amadeus_uq UNIQUE (checkout_id, amadeus_traveler_id),
  CONSTRAINT checkout_travelers_key_ck CHECK ((documents_ciphertext IS NULL AND discount_eligibility_ciphertext IS NULL) OR encryption_key_id IS NOT NULL)
);
CREATE INDEX checkout_travelers_saved_idx ON checkout_travelers (saved_traveler_id) WHERE saved_traveler_id IS NOT NULL;

-- Booking contacts entered in a checkout (Amadeus contacts[]: STANDARD, INVOICE ...).
CREATE TABLE checkout_contacts (
  id           text PRIMARY KEY CHECK (id LIKE 'cco\_%'),                    -- Checkout contact id (cco_ + ULID).
  checkout_id  text NOT NULL REFERENCES checkouts (id) ON DELETE CASCADE,    -- * Checkout.
  purpose      text NOT NULL DEFAULT 'STANDARD' CHECK (purpose IN ('STANDARD','INVOICE','STANDARD_WITHOUT_TRANSMISSION')), -- * Amadeus ContactPurpose.
  is_primary   boolean NOT NULL DEFAULT false,                               -- Receives confirmations and the guest booking token.
  first_name   text,                                                         -- addresseeName.firstName.
  last_name    text,                                                         -- addresseeName.lastName.
  company_name text,                                                         -- companyName (invoice contacts).
  email        text,                                                         -- * emailAddress.
  phones       jsonb NOT NULL DEFAULT '[]'::jsonb,                           -- phones [{deviceType, countryCallingCode, number}] (max 3).
  address      jsonb,                                                        -- address {lines[], postalCode, countryCode, cityName, stateName, postalBox}.
  language     text,                                                         -- Preferred language of communication.
  created_at   timestamptz NOT NULL DEFAULT now(),                           -- Row creation time.
  updated_at   timestamptz NOT NULL DEFAULT now()                            -- Last modification time.
);
CREATE INDEX checkout_contacts_checkout_idx ON checkout_contacts (checkout_id);
CREATE UNIQUE INDEX checkout_contacts_primary_uq ON checkout_contacts (checkout_id) WHERE is_primary;

-- Ancillary selections in a checkout (bags, seats, other services) per traveller and segment.
CREATE TABLE checkout_ancillaries (
  id                   text PRIMARY KEY CHECK (id LIKE 'can\_%'),            -- Selection id (can_ + ULID).
  checkout_id          text NOT NULL REFERENCES checkouts (id) ON DELETE CASCADE, -- * Checkout.
  checkout_traveler_id text REFERENCES checkout_travelers (id) ON DELETE CASCADE, -- * Traveller (NULL = all travellers when bookable per order).
  segment_id           text,                                                 -- Amadeus segment id (NULL = every segment / whole itinerary).
  type                 text NOT NULL CHECK (type IN ('CHECKED_BAGS','CABIN_BAGS','SEATS','MEALS','OTHER_SERVICES')), -- * Amadeus AdditionalServiceType.
  service_code         text,                                                 -- Option key: bag option id from included.bags, service name (PRIORITY_BOARDING ...) or chargeable seat id.
  quantity             smallint NOT NULL DEFAULT 1 CHECK (quantity BETWEEN 1 AND 9), -- Units (bags).
  weight               integer,                                              -- Weight per bag.
  weight_unit          text CHECK (weight_unit IN ('KG','LB')),              -- Weight unit.
  seat_number          text CHECK (seat_number ~ '^[1-9][0-9]{0,2}[A-Z]?$'), -- Selected seat (chargeableSeatNumber).
  currency             char(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),     -- Price currency.
  price_amount         numeric(12,2) NOT NULL DEFAULT 0,                     -- * Selling price of the selection.
  net_amount           numeric(12,2) NOT NULL DEFAULT 0,                     -- Amadeus price of the selection.
  details              jsonb NOT NULL DEFAULT '{}'::jsonb,                   -- Verbatim Amadeus option (bag / other-service entry of the pricing response).
  created_at           timestamptz NOT NULL DEFAULT now(),                   -- Row creation time.
  updated_at           timestamptz NOT NULL DEFAULT now(),                   -- Last modification time.
  CONSTRAINT checkout_ancillaries_uq UNIQUE NULLS NOT DISTINCT (checkout_id, checkout_traveler_id, segment_id, type, service_code),
  CONSTRAINT checkout_ancillaries_seat_ck CHECK (type <> 'SEATS' OR seat_number IS NOT NULL)
);
CREATE UNIQUE INDEX checkout_ancillaries_seat_uq ON checkout_ancillaries (checkout_traveler_id, segment_id) WHERE type = 'SEATS';

-- Special requests entered in a checkout (checkout.setRemarks, replaced as a whole). At create-order each becomes an
-- Amadeus remarks.general entry (subType GENERAL_MISCELLANEOUS) and a booking_remarks row (visible_to_customer = true).
CREATE TABLE checkout_remarks (
  id                  text PRIMARY KEY CHECK (id LIKE 'crm\_%'),             -- Checkout remark id (crm_ + ULID).
  checkout_id         text NOT NULL REFERENCES checkouts (id) ON DELETE CASCADE, -- * Checkout.
  text                text NOT NULL CHECK (length(text) BETWEEN 1 AND 110),  -- * Request text as entered (Amadeus remark character set; upper-cased and prefixed when sent).
  traveler_ids        text[] NOT NULL DEFAULT '{}',                          -- Amadeus traveller ids concerned (empty = all travellers).
  position            smallint NOT NULL DEFAULT 0 CHECK (position BETWEEN 0 AND 4), -- * Order of the request (at most 5 per checkout).
  source              text NOT NULL DEFAULT 'customer' CHECK (source IN ('customer','staff')), -- Entered by the customer or by staff in a console checkout.
  created_by_staff_id text,                                                  -- Staff id (stf_) by value when source = staff.
  created_at          timestamptz NOT NULL DEFAULT now(),                    -- Row creation time.
  updated_at          timestamptz NOT NULL DEFAULT now(),                    -- Last modification time.
  CONSTRAINT checkout_remarks_position_uq UNIQUE (checkout_id, position)
);

-- Bookings = Amadeus flight orders of the OTA (storefront, console or imported by record locator), customer or guest.
-- Status machine: pending -> confirmed -> ticketed | partially_ticketed -> cancelled ; pending -> failed.
CREATE TABLE bookings (
  id                    text PRIMARY KEY CHECK (id LIKE 'bkg\_%'),           -- Booking id (bkg_ + ULID).
  environment           text NOT NULL CHECK (environment IN ('test','live')), -- * Amadeus environment of the flight order.
  reference             text NOT NULL UNIQUE CHECK (reference ~ '^[A-Z0-9]{6,10}$'), -- * Velexis booking reference shown to customers (lookup with last name).
  channel               text NOT NULL DEFAULT 'storefront' CHECK (channel IN ('storefront','console','import')), -- Where the booking was created.
  customer_id           text REFERENCES customers (id) ON DELETE SET NULL,   -- * Customer (NULL = guest booking, accessed with booking tokens).
  checkout_id           text UNIQUE REFERENCES checkouts (id) ON DELETE SET NULL, -- Checkout that produced the booking (one booking per checkout).
  priced_offer_id       text REFERENCES priced_offers (id) ON DELETE SET NULL, -- Priced offer that was booked.
  created_by_staff_id   text,                                                -- Staff id (stf_) by value for console bookings/imports.
  status                text NOT NULL DEFAULT 'pending'
                        CHECK (status IN ('pending','confirmed','ticketed','partially_ticketed','cancelled','failed')), -- * Booking state.
  amadeus_order_id      text,                                                -- * Amadeus flight-order id (data.id).
  record_locator        text CHECK (record_locator ~ '^[A-Z0-9]{5,8}$'),     -- * Main record locator (associatedRecords[0].reference, Amadeus 1A).
  origin_system_code    text,                                                -- * originSystemCode of the main record, e.g. 1A.
  supplier_connection_id text,                                               -- Platform supplier connection (sc_) used, by value.
  queuing_office_id     text,                                                -- queuingOfficeId of the order.
  owner_office_id       text,                                                -- ownerOfficeId of the order.
  last_ticketing_date   date,                                                -- lastTicketingDate given by Amadeus.
  ticketing_deadline_at timestamptz,                                         -- * Absolute ticketing deadline (lastTicketingDate / ticketingAgreement in office time zone).
  ticketing_agreement   jsonb,                                               -- Amadeus ticketingAgreement {option, delay, dateTime, segmentIds}.
  automated_process     jsonb NOT NULL DEFAULT '[]'::jsonb,                  -- Amadeus automatedProcess [{code, queue{number,category}, text, delay, officeId, dateTime}].
  issue_requested       boolean NOT NULL DEFAULT false,                      -- Create-order was sent with issue=true.
  issued_at             timestamptz,                                         -- First ticket issuance.
  ticketing_status      text NOT NULL DEFAULT 'pending'
                        CHECK (ticketing_status IN ('pending','in_progress','issued','partially_issued','failed','manual_review','not_applicable')), -- * Issuance state (API IssuanceStatus); failed = retried by the issuance job until the deadline.
  ticketing_requested_at timestamptz,                                        -- When issuance was first requested (create-order issue=true, capture, staff).
  ticketing_attempts    integer NOT NULL DEFAULT 0 CHECK (ticketing_attempts >= 0), -- Flight Order Issue / issue=true attempts.
  ticketing_last_attempt_at timestamptz,                                     -- Last issuance attempt.
  ticketing_next_attempt_at timestamptz,                                     -- Next automatic retry of the issuance job (NULL = none scheduled).
  ticketing_error_code  text,                                                -- Public code of the last issuance failure (TICKETING_FAILED, PAYMENT_DECLINED ...).
  ticketing_error       text,                                                -- Details of the last issuance failure incl. Amadeus code (console only).
  trip_type             text CHECK (trip_type IN ('one_way','round_trip','multi_city')), -- Itinerary shape.
  origin_iata           char(3),                                             -- First departure airport (IATA, by value).
  destination_iata      char(3),                                             -- Main destination (IATA, by value).
  first_departure_at    timestamptz NOT NULL,                                -- * First segment departure (UTC) - upcoming/past ordering.
  last_arrival_at       timestamptz NOT NULL,                                -- * Last segment arrival (UTC) - a trip is past once this is over.
  validating_carrier    text CHECK (validating_carrier ~ '^[A-Z0-9]{2}$'),   -- Validating airline.
  travelers_count       smallint NOT NULL DEFAULT 1 CHECK (travelers_count BETWEEN 1 AND 18), -- Number of travellers.
  currency              char(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),    -- Currency of all totals.
  pricing_mode          text NOT NULL DEFAULT 'markup_rules' CHECK (pricing_mode IN ('markup_rules','net','override')), -- * How the selling price was set (console create/import may sell at net or at an override).
  markup_rule_id        text REFERENCES markup_rules (id) ON DELETE SET NULL, -- Markup rule applied (pricing_mode = markup_rules; NULL for net / override or a deleted rule).
  net_amount            numeric(12,2) NOT NULL,                              -- * Amadeus grandTotal incl. booked services (net cost).
  net_base_amount       numeric(12,2),                                       -- Amadeus base fares (price.base).
  net_fees_amount       numeric(12,2),                                       -- Amadeus fees (SUPPLIER, TICKETING, FORM_OF_PAYMENT).
  net_services_amount   numeric(12,2),                                       -- Amadeus additionalServices total (bags, seats, services).
  markup_amount         numeric(12,2) NOT NULL DEFAULT 0,                    -- Markup included in the selling total.
  fees_amount           numeric(12,2) NOT NULL DEFAULT 0,                    -- OTA service fees (fee_rules) included in the selling total, excluding card fees.
  card_fee_amount       numeric(12,2) NOT NULL DEFAULT 0,                    -- Credit-card fee charged to the customer (payments.card_fee_amount of the booking's payment).
  ancillaries_amount    numeric(12,2) NOT NULL DEFAULT 0,                    -- Selling amount of ancillaries.
  taxes_amount          numeric(12,2) NOT NULL DEFAULT 0,                    -- Amadeus taxes included (net taxes).
  total_amount          numeric(12,2) NOT NULL,                              -- * Selling total paid by the customer.
  amount_paid           numeric(12,2) NOT NULL DEFAULT 0,                    -- Captured payments.
  amount_refunded       numeric(12,2) NOT NULL DEFAULT 0,                    -- Refunded amount.
  contact_email         text NOT NULL,                                       -- * Primary contact e-mail (guest lookup and notifications).
  lead_last_name        text NOT NULL,                                       -- Upper-case last name of the lead traveller (reference + last name lookup).
  commissions           jsonb NOT NULL DEFAULT '[]'::jsonb,                  -- Amadeus commissions [{controls, values[], travelerIds, segmentIds}].
  form_of_payments      jsonb NOT NULL DEFAULT '[]'::jsonb,                  -- Redacted Amadeus formOfPayments (type, brand, last4, method, flightOfferIds; never PAN/CVV).
  form_of_identifications jsonb NOT NULL DEFAULT '[]'::jsonb,                -- Amadeus formOfIdentifications.
  order_snapshot        jsonb NOT NULL DEFAULT '{}'::jsonb,                  -- * Latest Amadeus flight-order data after the redaction rule (document, discount card and certificate numbers masked to last 4, card number masked, CVV dropped); full documents live in booking_travelers ciphertexts.
  order_included        jsonb,                                               -- included.bags of the last GET (include=bags) / fare rule eligibility.
  order_dictionaries    jsonb,                                               -- Amadeus dictionaries of the last response.
  last_synced_at        timestamptz,                                         -- * Last refresh from Flight Order Management GET.
  sync_error            text,                                                -- Last synchronisation error.
  cancelled_at          timestamptz,                                         -- When the order was cancelled.
  cancelled_by          text CHECK (cancelled_by IN ('customer','staff','airline','system')), -- Who cancelled it.
  cancel_reason         text,                                                -- Free-text cancellation reason.
  failure_code          text,                                                -- Public error code when status = failed.
  failure_message       text,                                                -- Failure details (console only).
  internal_notes        text,                                                -- Staff notes, never shown to customers.
  tags                  text[] NOT NULL DEFAULT '{}',                        -- Staff tags for filtering.
  metadata              jsonb NOT NULL DEFAULT '{}'::jsonb,                  -- OTA-defined key/values.
  version               integer NOT NULL DEFAULT 1,                          -- Optimistic-locking counter (If-Match / ETag).
  created_at            timestamptz NOT NULL DEFAULT now(),                  -- * Booking time.
  updated_at            timestamptz NOT NULL DEFAULT now(),                  -- Last modification time.
  CONSTRAINT bookings_cancelled_ck CHECK (status <> 'cancelled' OR cancelled_at IS NOT NULL),
  CONSTRAINT bookings_trip_ck CHECK (last_arrival_at >= first_departure_at),
  CONSTRAINT bookings_ticketing_ck CHECK ((status <> 'ticketed' OR ticketing_status = 'issued') AND (status <> 'failed' OR ticketing_status = 'not_applicable')),
  CONSTRAINT bookings_net_pricing_ck CHECK (pricing_mode <> 'net' OR markup_amount = 0)
);
CREATE UNIQUE INDEX bookings_amadeus_order_uq ON bookings (environment, amadeus_order_id) WHERE amadeus_order_id IS NOT NULL;
CREATE UNIQUE INDEX bookings_record_locator_uq ON bookings (environment, record_locator, origin_system_code) WHERE record_locator IS NOT NULL;
-- My trips: upcoming sorts by departure; past and cancelled default to -departure (bookings.list).
CREATE INDEX bookings_customer_upcoming_idx ON bookings (customer_id, first_departure_at, id) WHERE status IN ('pending','confirmed','ticketed','partially_ticketed');
CREATE INDEX bookings_customer_past_idx ON bookings (customer_id, first_departure_at DESC, id DESC) INCLUDE (last_arrival_at) WHERE status IN ('pending','confirmed','ticketed','partially_ticketed');
CREATE INDEX bookings_customer_cancelled_idx ON bookings (customer_id, first_departure_at DESC, id DESC) WHERE status = 'cancelled';
-- Console list (every index leads with environment: test keys never see live rows).
CREATE INDEX bookings_created_idx ON bookings (environment, created_at DESC, id DESC);
CREATE INDEX bookings_status_idx ON bookings (environment, status, created_at DESC);
CREATE INDEX bookings_ticketing_deadline_idx ON bookings (environment, ticketing_deadline_at, id);
CREATE INDEX bookings_ticketing_status_idx ON bookings (environment, ticketing_status, ticketing_deadline_at);
CREATE INDEX bookings_ticketing_retry_idx ON bookings (ticketing_next_attempt_at) WHERE ticketing_status IN ('pending','failed') AND ticketing_next_attempt_at IS NOT NULL;
CREATE INDEX bookings_departure_idx ON bookings (environment, first_departure_at);
CREATE INDEX bookings_total_idx ON bookings (environment, total_amount, id);
CREATE INDEX bookings_contact_email_idx ON bookings (environment, lower(contact_email), created_at DESC);
CREATE INDEX bookings_lead_last_name_idx ON bookings (lead_last_name text_pattern_ops);
CREATE INDEX bookings_validating_carrier_idx ON bookings (environment, validating_carrier, created_at DESC);
CREATE INDEX bookings_created_by_staff_idx ON bookings (environment, created_by_staff_id, created_at DESC) WHERE created_by_staff_id IS NOT NULL;
CREATE INDEX bookings_tags_idx ON bookings USING gin (tags);
CREATE INDEX bookings_sync_idx ON bookings (last_synced_at NULLS FIRST) WHERE status IN ('pending','confirmed','ticketed','partially_ticketed');
CREATE INDEX bookings_priced_offer_idx ON bookings (priced_offer_id) WHERE priced_offer_id IS NOT NULL;
CREATE INDEX bookings_markup_rule_idx ON bookings (markup_rule_id) WHERE markup_rule_id IS NOT NULL;

-- All Amadeus associatedRecords of an order (Amadeus 1A and other-airline record locators, e.g. codeshare/operating PNRs).
CREATE TABLE booking_associated_records (
  id                 text PRIMARY KEY CHECK (id LIKE 'bar\_%'),              -- Associated record id (bar_ + ULID).
  booking_id         text NOT NULL REFERENCES bookings (id) ON DELETE CASCADE, -- * Booking.
  reference          text NOT NULL,                                          -- * Record locator (Amadeus or other airline).
  origin_system_code text NOT NULL,                                          -- * System that created the record, e.g. 1A or a carrier code.
  creation_date      timestamp,                                              -- creationDate of the referenced reservation (local, as given).
  flight_offer_id    text,                                                   -- Amadeus flightOfferId the record relates to.
  is_primary         boolean NOT NULL DEFAULT false,                         -- The record copied into bookings.record_locator.
  created_at         timestamptz NOT NULL DEFAULT now(),                     -- Row creation time.
  updated_at         timestamptz NOT NULL DEFAULT now(),                     -- Last modification time.
  CONSTRAINT booking_associated_records_uq UNIQUE (booking_id, reference, origin_system_code)
);
CREATE INDEX booking_associated_records_lookup_idx ON booking_associated_records (reference, origin_system_code);

-- Travellers of a booking (Amadeus travelers[]), documents encrypted by the application.
CREATE TABLE booking_travelers (
  id                         text PRIMARY KEY CHECK (id LIKE 'btr\_%'),      -- Booking traveller id (btr_ + ULID).
  booking_id                 text NOT NULL REFERENCES bookings (id) ON DELETE CASCADE, -- * Booking.
  saved_traveler_id          text REFERENCES saved_travelers (id) ON DELETE SET NULL, -- Saved traveller it came from.
  amadeus_traveler_id        text NOT NULL,                                  -- * Amadeus traveler id in the order ("1", "2" ...).
  traveler_type              text NOT NULL CHECK (traveler_type IN ('ADULT','CHILD','SENIOR','YOUNG','HELD_INFANT','SEATED_INFANT','STUDENT')), -- * Amadeus TravelerType.
  fare_option                text,                                           -- Amadeus fareOption (STANDARD, residents, ...).
  associated_adult_id        text,                                           -- Adult travelerId of a held infant.
  first_name                 text NOT NULL,                                  -- * name.firstName.
  middle_name                text,                                           -- name.middleName.
  last_name                  text NOT NULL,                                  -- * name.lastName.
  second_last_name           text,                                           -- name.secondLastName.
  date_of_birth              date,                                           -- dateOfBirth.
  gender                     text CHECK (gender IN ('MALE','FEMALE','UNSPECIFIED','UNDISCLOSED')), -- Amadeus StakeholderGender.
  contact                    jsonb,                                          -- Traveller contact {emailAddress, phones[], address, language}.
  documents_ciphertext       bytea,                                          -- Encrypted Amadeus documents[] (full identity documents).
  discount_eligibility_ciphertext bytea,                                     -- Encrypted Amadeus discountEligibility[] (resident card / certificate numbers).
  encryption_key_id          text,                                           -- KMS key id wrapping the row's data key (documents and discount ciphertexts).
  document_type              text CHECK (document_type IN ('VISA','PASSPORT','IDENTITY_CARD','KNOWN_TRAVELER','REDRESS')), -- Type of the main document (clear, display).
  document_last4             text CHECK (length(document_last4) <= 4),       -- Last 4 characters of the main document number.
  document_expiry_date       date,                                           -- Expiry of the main document.
  document_issuance_country  char(2) CHECK (document_issuance_country ~ '^[A-Z]{2}$'), -- Issuing country of the main document.
  document_nationality       char(2) CHECK (document_nationality ~ '^[A-Z]{2}$'), -- Nationality on the main document.
  loyalty_programs           jsonb NOT NULL DEFAULT '[]'::jsonb,             -- Amadeus loyaltyPrograms [{programOwner, id}].
  emergency_contact          jsonb,                                          -- Amadeus emergencyContact.
  created_at                 timestamptz NOT NULL DEFAULT now(),             -- Row creation time.
  updated_at                 timestamptz NOT NULL DEFAULT now(),             -- Last modification time.
  CONSTRAINT booking_travelers_amadeus_uq UNIQUE (booking_id, amadeus_traveler_id),
  CONSTRAINT booking_travelers_key_ck CHECK ((documents_ciphertext IS NULL AND discount_eligibility_ciphertext IS NULL) OR encryption_key_id IS NOT NULL)
);
CREATE INDEX booking_travelers_last_name_idx ON booking_travelers (lower(last_name) text_pattern_ops);
CREATE INDEX booking_travelers_saved_idx ON booking_travelers (saved_traveler_id) WHERE saved_traveler_id IS NOT NULL;

-- Contacts of a booking (Amadeus contacts[]).
CREATE TABLE booking_contacts (
  id           text PRIMARY KEY CHECK (id LIKE 'bco\_%'),                    -- Booking contact id (bco_ + ULID).
  booking_id   text NOT NULL REFERENCES bookings (id) ON DELETE CASCADE,     -- * Booking.
  purpose      text NOT NULL DEFAULT 'STANDARD' CHECK (purpose IN ('STANDARD','INVOICE','STANDARD_WITHOUT_TRANSMISSION')), -- * Amadeus ContactPurpose.
  is_primary   boolean NOT NULL DEFAULT false,                               -- Primary contact (copied to bookings.contact_email).
  first_name   text,                                                         -- addresseeName.firstName.
  last_name    text,                                                         -- addresseeName.lastName.
  company_name text,                                                         -- companyName.
  email        text,                                                         -- * emailAddress.
  phones       jsonb NOT NULL DEFAULT '[]'::jsonb,                           -- phones [{deviceType, countryCallingCode, number}].
  address      jsonb,                                                        -- address {lines[], postalCode, countryCode, cityName, stateName, postalBox}.
  language     text,                                                         -- Preferred language.
  created_at   timestamptz NOT NULL DEFAULT now(),                           -- Row creation time.
  updated_at   timestamptz NOT NULL DEFAULT now()                            -- Last modification time.
);
CREATE INDEX booking_contacts_booking_idx ON booking_contacts (booking_id);
CREATE INDEX booking_contacts_email_idx ON booking_contacts (lower(email));
CREATE UNIQUE INDEX booking_contacts_primary_uq ON booking_contacts (booking_id) WHERE is_primary;

-- Flight segments of a booking (itineraries[].segments[] of each flight offer in the order).
CREATE TABLE booking_segments (
  id                     text PRIMARY KEY CHECK (id LIKE 'seg\_%'),          -- Booking segment id (seg_ + ULID).
  booking_id             text NOT NULL REFERENCES bookings (id) ON DELETE CASCADE, -- * Booking.
  amadeus_flight_offer_id text NOT NULL DEFAULT '1',                         -- Flight offer id inside the order.
  amadeus_segment_id     text NOT NULL,                                      -- * Amadeus segment id (referenced by tickets, remarks, services).
  itinerary_index        smallint NOT NULL,                                  -- * 0-based itinerary (bound) index.
  segment_index          smallint NOT NULL,                                  -- * 0-based position inside the itinerary.
  carrier_code           text NOT NULL CHECK (carrier_code ~ '^[A-Z0-9]{2}$'), -- * Marketing carrier (IATA, by value).
  flight_number          text NOT NULL CHECK (flight_number ~ '^[0-9]{1,4}[A-Z]?$'), -- * Flight number.
  operating_carrier_code text,                                               -- Operating carrier (codeshare).
  aircraft_code          text,                                               -- Aircraft type (IATA, by value).
  departure_iata         char(3) NOT NULL,                                   -- * Departure airport (IATA, by value).
  departure_terminal     text,                                               -- Departure terminal.
  departure_local        timestamp NOT NULL,                                 -- Departure local date-time (as Amadeus gives it).
  departure_at           timestamptz NOT NULL,                               -- * Departure instant (UTC, via airport time zone).
  arrival_iata           char(3) NOT NULL,                                   -- * Arrival airport.
  arrival_terminal       text,                                               -- Arrival terminal.
  arrival_local          timestamp NOT NULL,                                 -- Arrival local date-time.
  arrival_at             timestamptz NOT NULL,                               -- * Arrival instant (UTC).
  duration_minutes       integer,                                            -- Segment duration.
  number_of_stops        smallint NOT NULL DEFAULT 0,                        -- Technical stops.
  stops                  jsonb,                                              -- Amadeus stops [{iataCode, duration, arrivalAt, departureAt}].
  cabin                  text CHECK (cabin IN ('ECONOMY','PREMIUM_ECONOMY','BUSINESS','FIRST')), -- * Cabin (of the lead traveller).
  booking_class          text CHECK (booking_class ~ '^[A-Z]$'),             -- * Booking class / RBD.
  fare_basis             text,                                               -- * Fare basis code.
  branded_fare           text,                                               -- * Branded fare (fare family) name, e.g. LIGHTONE.
  included_checked_bags  jsonb,                                              -- includedCheckedBags {quantity, weight, weightUnit}.
  fare_details           jsonb NOT NULL DEFAULT '[]'::jsonb,                 -- Per-traveller fareDetailsBySegment entries for this segment.
  co2_emissions          jsonb,                                              -- Amadeus co2Emissions.
  status                 text NOT NULL DEFAULT 'CONFIRMED' CHECK (status IN ('CONFIRMED','WAITLISTED','CANCELLED','PENDING','DENIED')), -- * Amadeus bookingStatus.
  segment_type           text NOT NULL DEFAULT 'ACTIVE' CHECK (segment_type IN ('ACTIVE','PASSIVE','GHOST','STAFF')), -- Amadeus segmentType.
  is_flown               boolean NOT NULL DEFAULT false,                     -- Amadeus isFlown.
  created_at             timestamptz NOT NULL DEFAULT now(),                 -- Row creation time.
  updated_at             timestamptz NOT NULL DEFAULT now(),                 -- Last modification time.
  CONSTRAINT booking_segments_amadeus_uq UNIQUE (booking_id, amadeus_flight_offer_id, amadeus_segment_id),
  CONSTRAINT booking_segments_time_ck CHECK (arrival_at >= departure_at)
);
CREATE INDEX booking_segments_booking_idx ON booking_segments (booking_id, itinerary_index, segment_index);
CREATE INDEX booking_segments_flight_idx ON booking_segments (carrier_code, flight_number, departure_local);
CREATE INDEX booking_segments_departure_idx ON booking_segments (departure_at);

-- Issued travel documents (Amadeus tickets[] / AirTravelDocument: e-tickets and EMDs).
CREATE TABLE booking_tickets (
  id                     text PRIMARY KEY CHECK (id LIKE 'tkt\_%'),          -- Ticket id (tkt_ + ULID).
  booking_id             text NOT NULL REFERENCES bookings (id) ON DELETE CASCADE, -- * Booking.
  booking_traveler_id    text REFERENCES booking_travelers (id) ON DELETE SET NULL, -- * Ticketed traveller.
  amadeus_traveler_id    text,                                               -- travelerId as given by Amadeus.
  document_type          text NOT NULL CHECK (document_type IN ('ETICKET','PTICKET','EMD','MCO')), -- * Amadeus documentType.
  document_number        text NOT NULL CHECK (document_number ~ '^[0-9]{3}-?[0-9]{6,13}$'), -- * Document number prefixed by the airline accounting code.
  status                 text NOT NULL DEFAULT 'ISSUED' CHECK (status IN ('ISSUED','REFUNDED','VOID','ORIGINAL','EXCHANGED')), -- * Amadeus documentStatus.
  segment_ids            text[] NOT NULL DEFAULT '{}',                       -- Amadeus segment ids covered.
  validating_carrier     text,                                               -- Issuing airline.
  currency               char(3) CHECK (currency ~ '^[A-Z]{3}$'),            -- Price currency.
  base_amount            numeric(12,2),                                      -- Fare without taxes.
  taxes_amount           numeric(12,2),                                      -- Taxes.
  total_amount           numeric(12,2),                                      -- * Document total.
  issued_at              timestamptz,                                        -- * Issue time.
  issued_by_staff_id     text,                                               -- Staff id (stf_) by value when issued from the console.
  exchanged_to_ticket_id text REFERENCES booking_tickets (id) ON DELETE SET NULL, -- New document when this one was EXCHANGED.
  details                jsonb NOT NULL DEFAULT '{}'::jsonb,                 -- Verbatim AirTravelDocument.
  created_at             timestamptz NOT NULL DEFAULT now(),                 -- Row creation time.
  updated_at             timestamptz NOT NULL DEFAULT now(),                 -- Last modification time.
  CONSTRAINT booking_tickets_number_uq UNIQUE (booking_id, document_number)
);
CREATE INDEX booking_tickets_number_idx ON booking_tickets (document_number);
CREATE INDEX booking_tickets_traveler_idx ON booking_tickets (booking_traveler_id);
CREATE INDEX booking_tickets_exchanged_idx ON booking_tickets (exchanged_to_ticket_id) WHERE exchanged_to_ticket_id IS NOT NULL;

-- Additional services of a booking (Amadeus additionalServices: bags, seats, meals, other services).
CREATE TABLE booking_ancillaries (
  id                  text PRIMARY KEY CHECK (id LIKE 'anc\_%'),             -- Ancillary id (anc_ + ULID).
  booking_id          text NOT NULL REFERENCES bookings (id) ON DELETE CASCADE, -- * Booking.
  booking_traveler_id text REFERENCES booking_travelers (id) ON DELETE CASCADE, -- * Traveller (NULL = whole order).
  booking_segment_id  text REFERENCES booking_segments (id) ON DELETE CASCADE, -- * Segment (NULL = all segments / itinerary).
  type                text NOT NULL CHECK (type IN ('CHECKED_BAGS','CABIN_BAGS','SEATS','MEALS','OTHER_SERVICES')), -- * Amadeus AdditionalServiceType.
  service_code        text,                                                  -- Service name (PRIORITY_BOARDING, AIRPORT_CHECKIN, FAST_TRACK), bag option id or seat id.
  quantity            smallint NOT NULL DEFAULT 1 CHECK (quantity BETWEEN 1 AND 9), -- Units.
  weight              integer,                                               -- Weight per bag.
  weight_unit         text CHECK (weight_unit IN ('KG','LB')),               -- Weight unit.
  seat_number         text CHECK (seat_number ~ '^[1-9][0-9]{0,2}[A-Z]?$'),  -- Seat number for SEATS.
  currency            char(3) CHECK (currency ~ '^[A-Z]{3}$'),               -- Price currency.
  price_amount        numeric(12,2) NOT NULL DEFAULT 0,                      -- * Selling price.
  net_amount          numeric(12,2) NOT NULL DEFAULT 0,                      -- Amadeus price.
  status              text NOT NULL DEFAULT 'requested' CHECK (status IN ('requested','confirmed','issued','cancelled','failed')), -- * Service state (issued = EMD issued).
  source              text NOT NULL DEFAULT 'checkout' CHECK (source IN ('checkout','post_booking','airline')), -- Booked in checkout, added later (PATCH) or by the airline.
  emd_ticket_id       text REFERENCES booking_tickets (id) ON DELETE SET NULL, -- EMD that paid for the service.
  details             jsonb NOT NULL DEFAULT '{}'::jsonb,                    -- Verbatim Amadeus service structure (chargeableCheckedBags, chargeableSeat ...).
  created_at          timestamptz NOT NULL DEFAULT now(),                    -- Row creation time.
  updated_at          timestamptz NOT NULL DEFAULT now()                     -- Last modification time.
);
CREATE INDEX booking_ancillaries_booking_idx ON booking_ancillaries (booking_id);
CREATE INDEX booking_ancillaries_traveler_idx ON booking_ancillaries (booking_traveler_id);
CREATE INDEX booking_ancillaries_segment_idx ON booking_ancillaries (booking_segment_id);
CREATE INDEX booking_ancillaries_emd_idx ON booking_ancillaries (emd_ticket_id) WHERE emd_ticket_id IS NOT NULL;
CREATE UNIQUE INDEX booking_ancillaries_seat_uq ON booking_ancillaries (booking_traveler_id, booking_segment_id) WHERE type = 'SEATS' AND status <> 'cancelled';

-- Amadeus remarks of a booking (general and airline remarks).
CREATE TABLE booking_remarks (
  id                  text PRIMARY KEY CHECK (id LIKE 'rmk\_%'),             -- Remark id (rmk_ + ULID).
  booking_id          text NOT NULL REFERENCES bookings (id) ON DELETE CASCADE, -- * Booking.
  kind                text NOT NULL CHECK (kind IN ('general','airline')),   -- * remarks.general or remarks.airline.
  sub_type            text NOT NULL,                                         -- * GeneralRemarkType or AirlineRemarkType.
  category            char(1) CHECK (category ~ '^[A-Z]$'),                  -- General remark category letter.
  airline_code        text,                                                  -- Airline of an airline remark (YY = all).
  keyword             text,                                                  -- Keyword code (airline KEYWORD remarks).
  text                text NOT NULL,                                         -- * Remark free text.
  traveler_ids        text[] NOT NULL DEFAULT '{}',                          -- Amadeus traveler ids concerned.
  flight_offer_ids    text[] NOT NULL DEFAULT '{}',                          -- Amadeus flight offer ids concerned.
  visible_to_customer boolean NOT NULL DEFAULT false,                        -- Whether customer scope may display it (never for CONFIDENTIAL).
  created_by_staff_id text,                                                  -- Staff id (stf_) by value.
  created_at          timestamptz NOT NULL DEFAULT now(),                    -- Row creation time.
  updated_at          timestamptz NOT NULL DEFAULT now(),                    -- Last modification time.
  CONSTRAINT booking_remarks_sub_type_ck CHECK (
    (kind = 'general' AND sub_type IN ('GENERAL_MISCELLANEOUS','CONFIDENTIAL','INVOICE','QUALITY_CONTROL','BACKOFFICE','FULFILLMENT','ITINERARY','TICKETING_MISCELLANEOUS','TOUR_CODE'))
    OR (kind = 'airline' AND sub_type IN ('OTHER_SERVICE_INFORMATION','KEYWORD','OTHER_SERVICE','CLIENT_ID','ADVANCED_TICKET_TIME_LIMIT') AND airline_code IS NOT NULL)),
  CONSTRAINT booking_remarks_confidential_ck CHECK (NOT (sub_type = 'CONFIDENTIAL' AND visible_to_customer))
);
CREATE INDEX booking_remarks_booking_idx ON booking_remarks (booking_id);

-- Generated documents of a booking (e-ticket receipts, itineraries, invoices) stored in object storage.
CREATE TABLE booking_documents (
  id                text PRIMARY KEY CHECK (id LIKE 'doc\_%'),               -- Document id (doc_ + ULID).
  booking_id        text NOT NULL REFERENCES bookings (id) ON DELETE CASCADE, -- * Booking.
  booking_ticket_id text REFERENCES booking_tickets (id) ON DELETE SET NULL,  -- Ticket an e-ticket / EMD receipt belongs to.
  kind              text NOT NULL CHECK (kind IN ('e_ticket_receipt','emd_receipt','itinerary','invoice','credit_note')), -- * Document kind.
  status            text NOT NULL DEFAULT 'ready' CHECK (status IN ('pending','ready','failed','superseded')), -- * Generation state.
  locale            text NOT NULL DEFAULT 'en',                              -- Language of the document.
  file_name         text NOT NULL,                                           -- Download file name.
  content_type      text NOT NULL DEFAULT 'application/pdf',                 -- MIME type.
  size_bytes        integer CHECK (size_bytes >= 0),                         -- File size.
  storage_key       text NOT NULL UNIQUE,                                    -- * Object-storage key (bucket path, server-side encrypted).
  content_hash      text NOT NULL CHECK (content_hash ~ '^[0-9a-f]{64}$'),   -- * SHA-256 of the file (integrity, deduplication).
  encryption_key_id text,                                                    -- KMS key used for object encryption.
  invoice_number    text,                                                    -- Legal invoice number (kind = invoice / credit_note).
  generated_by      text NOT NULL DEFAULT 'system' CHECK (generated_by IN ('system','staff')), -- Who generated it.
  sent_at           timestamptz,                                             -- When it was e-mailed to the contact.
  created_at        timestamptz NOT NULL DEFAULT now(),                      -- Row creation time.
  updated_at        timestamptz NOT NULL DEFAULT now()                       -- Last modification time.
);
CREATE INDEX booking_documents_booking_idx ON booking_documents (booking_id, kind);
CREATE INDEX booking_documents_ticket_idx ON booking_documents (booking_ticket_id) WHERE booking_ticket_id IS NOT NULL;
CREATE UNIQUE INDEX booking_documents_invoice_uq ON booking_documents (invoice_number) WHERE invoice_number IS NOT NULL;

-- Guest access tokens for a booking (X-Booking-Token), stored hashed.
CREATE TABLE booking_access_tokens (
  id           text PRIMARY KEY CHECK (id LIKE 'bat\_%'),                    -- Token id (bat_ + ULID).
  booking_id   text NOT NULL REFERENCES bookings (id) ON DELETE CASCADE,     -- * Booking the token grants access to.
  token_hash   text NOT NULL UNIQUE,                                         -- * SHA-256 of the token.
  issued_via   text NOT NULL CHECK (issued_via IN ('booking_created','lookup','email_link','staff')), -- How it was issued.
  created_ip   inet,                                                         -- IP that obtained it.
  expires_at   timestamptz NOT NULL,                                         -- * Expiry.
  last_used_at timestamptz,                                                  -- Last use.
  use_count    integer NOT NULL DEFAULT 0,                                   -- Number of authenticated requests.
  revoked_at   timestamptz,                                                  -- * Revocation time.
  created_at   timestamptz NOT NULL DEFAULT now(),                           -- Issue time.
  updated_at   timestamptz NOT NULL DEFAULT now()                            -- Last modification time.
);
CREATE INDEX booking_access_tokens_booking_idx ON booking_access_tokens (booking_id) WHERE revoked_at IS NULL;
CREATE INDEX booking_access_tokens_expires_idx ON booking_access_tokens (expires_at);

-- Customer payments collected through the tenant's payment provider (no card data: PSP references only).
-- Status machine: requires_payment_method -> requires_action -> processing -> authorized -> captured
--                 -> partially_refunded -> refunded ; authorized -> canceled ; any pre-capture state -> failed.
CREATE TABLE payments (
  id                     text PRIMARY KEY CHECK (id LIKE 'pay\_%'),          -- Payment id (pay_ + ULID).
  environment            text NOT NULL CHECK (environment IN ('test','live')), -- * Payment provider environment.
  checkout_id            text REFERENCES checkouts (id) ON DELETE SET NULL,  -- * Checkout that started the payment.
  booking_id             text REFERENCES bookings (id) ON DELETE RESTRICT,   -- * Booking paid (set when the booking exists; post-booking changes too).
  customer_id            text REFERENCES customers (id) ON DELETE SET NULL,  -- Paying customer (NULL = guest).
  provider               text NOT NULL CHECK (provider IN ('stripe','adyen','checkout_com','paypal','manual')), -- * Payment service provider.
  provider_connection_id text,                                               -- platform.payment_provider_connections id (ppc_) by value.
  provider_payment_id    text,                                               -- * PSP payment id (e.g. PaymentIntent id).
  provider_customer_id   text,                                               -- PSP customer id.
  method                 text NOT NULL DEFAULT 'card' CHECK (method IN ('card','apple_pay','google_pay','paypal','bank_transfer','agency_credit','cash')), -- Payment method.
  capture_method         text NOT NULL DEFAULT 'manual' CHECK (capture_method IN ('automatic','manual')), -- Capture immediately or after booking success.
  currency               char(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),   -- Payment currency.
  amount                 numeric(12,2) NOT NULL CHECK (amount > 0),          -- * Amount requested.
  card_fee_amount        numeric(12,2) NOT NULL DEFAULT 0,                   -- Credit-card fee included in amount.
  amount_authorized      numeric(12,2) NOT NULL DEFAULT 0,                   -- Amount authorised.
  amount_captured        numeric(12,2) NOT NULL DEFAULT 0,                   -- * Amount captured.
  amount_refunded        numeric(12,2) NOT NULL DEFAULT 0,                   -- * Amount refunded.
  status                 text NOT NULL DEFAULT 'requires_payment_method'
                         CHECK (status IN ('requires_payment_method','requires_action','processing','authorized','captured','partially_refunded','refunded','canceled','failed')), -- * Payment state.
  card_brand             text,                                               -- Card brand (Amadeus PaymentBrand naming).
  card_bin               char(6) CHECK (card_bin ~ '^[0-9]{6}$'),            -- First 6 digits (credit-card fee lookup via Flight Offers Price payments.binNumber).
  card_last4             char(4) CHECK (card_last4 ~ '^[0-9]{4}$'),          -- Last 4 digits.
  card_exp_month         smallint CHECK (card_exp_month BETWEEN 1 AND 12),   -- Card expiry month.
  card_exp_year          smallint,                                           -- Card expiry year.
  three_ds               jsonb,                                              -- 3-D Secure outcome (version, eci, cavv, dsTransactionId ...) for Amadeus threeDomainSecure.
  next_action            jsonb,                                              -- Pending customer action (redirect / SDK challenge).
  failure_code           text,                                               -- PSP / public failure code.
  failure_message        text,                                               -- Failure details.
  authorized_at          timestamptz,                                        -- Authorisation time.
  captured_at            timestamptz,                                        -- Capture time.
  canceled_at            timestamptz,                                        -- Void time.
  metadata               jsonb NOT NULL DEFAULT '{}'::jsonb,                 -- OTA-defined key/values.
  version                integer NOT NULL DEFAULT 1,                         -- Optimistic-locking counter.
  created_at             timestamptz NOT NULL DEFAULT now(),                 -- * Creation time.
  updated_at             timestamptz NOT NULL DEFAULT now(),                 -- Last modification time.
  CONSTRAINT payments_amounts_ck CHECK (amount_captured <= amount AND amount_refunded <= amount_captured AND amount_authorized <= amount)
);
CREATE UNIQUE INDEX payments_provider_uq ON payments (provider, provider_payment_id) WHERE provider_payment_id IS NOT NULL;
CREATE INDEX payments_booking_idx ON payments (booking_id) WHERE booking_id IS NOT NULL;
CREATE INDEX payments_checkout_idx ON payments (checkout_id) WHERE checkout_id IS NOT NULL;
CREATE INDEX payments_customer_idx ON payments (customer_id, created_at DESC) WHERE customer_id IS NOT NULL;
CREATE INDEX payments_status_idx ON payments (environment, status, created_at DESC);

-- Append-only history of a payment (API calls, PSP webhooks, status transitions).
CREATE TABLE payment_events (
  id                text PRIMARY KEY CHECK (id LIKE 'pev\_%'),               -- Payment event id (pev_ + ULID).
  payment_id        text NOT NULL REFERENCES payments (id) ON DELETE CASCADE, -- * Payment.
  type              text NOT NULL,                                           -- * Event type, e.g. payment.authorized, webhook.charge.refunded.
  source            text NOT NULL CHECK (source IN ('api','webhook','system','staff')), -- Origin of the event.
  provider_event_id text,                                                    -- PSP event id (webhook de-duplication).
  status_from       text,                                                    -- Status before.
  status_to         text,                                                    -- Status after.
  amount            numeric(12,2),                                           -- Amount concerned.
  currency          char(3) CHECK (currency ~ '^[A-Z]{3}$'),                 -- Currency of amount.
  payload           jsonb NOT NULL DEFAULT '{}'::jsonb,                      -- Redacted provider payload.
  created_at        timestamptz NOT NULL DEFAULT now(),                      -- * Event time.
  updated_at        timestamptz NOT NULL DEFAULT now()                       -- Equal to created_at (append-only).
);
CREATE INDEX payment_events_payment_idx ON payment_events (payment_id, created_at);
CREATE UNIQUE INDEX payment_events_provider_uq ON payment_events (provider_event_id) WHERE provider_event_id IS NOT NULL;

-- Refunds of captured payments (customer cancellation, schedule change, goodwill).
-- Status machine: pending -> processing -> succeeded | failed ; pending -> canceled.
CREATE TABLE refunds (
  id                     text PRIMARY KEY CHECK (id LIKE 'rfd\_%'),          -- Refund id (rfd_ + ULID).
  payment_id             text NOT NULL REFERENCES payments (id) ON DELETE RESTRICT, -- * Refunded payment.
  booking_id             text REFERENCES bookings (id) ON DELETE RESTRICT,   -- * Booking concerned.
  currency               char(3) NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),   -- Refund currency.
  amount                 numeric(12,2) NOT NULL CHECK (amount > 0),          -- * Amount refunded to the customer.
  supplier_refund_amount numeric(12,2),                                      -- Amount the airline refunds (Amadeus refundingPreview.totalRefund).
  penalty_amount         numeric(12,2),                                      -- Airline cancellation penalty retained.
  reason                 text NOT NULL CHECK (reason IN ('customer_request','booking_cancelled','schedule_change','duplicate','fraud','goodwill','other')), -- * Reason.
  reason_note            text,                                               -- Free-text explanation.
  status                 text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','processing','succeeded','failed','canceled')), -- * Refund state.
  provider_refund_id     text,                                               -- PSP refund id.
  requested_by_type      text NOT NULL CHECK (requested_by_type IN ('customer','staff','system')), -- Requester type.
  requested_by_id        text,                                               -- cus_ or stf_ id by value.
  failure_reason         text,                                               -- Why it failed.
  processed_at           timestamptz,                                        -- Completion time.
  version                integer NOT NULL DEFAULT 1,                         -- Optimistic-locking counter.
  created_at             timestamptz NOT NULL DEFAULT now(),                 -- Request time.
  updated_at             timestamptz NOT NULL DEFAULT now()                  -- Last modification time.
);
CREATE INDEX refunds_payment_idx ON refunds (payment_id);
CREATE INDEX refunds_booking_idx ON refunds (booking_id) WHERE booking_id IS NOT NULL;
CREATE UNIQUE INDEX refunds_provider_uq ON refunds (provider_refund_id) WHERE provider_refund_id IS NOT NULL;

-- Log of every Amadeus call (redacted request/response), for support, replay and SLA reporting.
CREATE TABLE supplier_requests (
  id                   text PRIMARY KEY CHECK (id LIKE 'sreq\_%'),           -- Supplier request id (sreq_ + ULID).
  environment          text NOT NULL CHECK (environment IN ('test','live')), -- * Amadeus environment.
  provider             text NOT NULL DEFAULT 'amadeus' CHECK (provider IN ('amadeus')), -- Supplier.
  operation            text NOT NULL,                                        -- * Velexis use case / SDK method, e.g. bookings.create.
  amadeus_api          text NOT NULL CHECK (amadeus_api IN ('Authorization','FlightOffersSearch','FlightAvailabilitiesSearch','BrandedFaresUpsell','FlightOffersPrice','FlightCreateOrders','FlightOrderIssue','FlightOrderManagement','GetFlightOrderByRecordLocator','QueueList')), -- * Amadeus spec (file prefix).
  amadeus_operation_id text NOT NULL,                                        -- * Amadeus operationId, e.g. createFligtOrders, quoteAirOffers.
  http_method          text NOT NULL CHECK (http_method IN ('GET','POST','PATCH','DELETE')), -- HTTP method.
  path                 text NOT NULL,                                        -- Request path incl. query (no host, secrets stripped).
  office_id            text,                                                 -- Amadeus office acted for.
  http_status          smallint,                                             -- * HTTP status returned (NULL = no response).
  outcome              text NOT NULL CHECK (outcome IN ('success','client_error','server_error','timeout','network_error')), -- * Classified outcome.
  error_codes          integer[] NOT NULL DEFAULT '{}',                      -- Amadeus error codes (e.g. 4926, 32171, 2552).
  duration_ms          integer,                                              -- * Latency.
  correlation_id       text,                                                 -- Amadeus correlation id (ama-request-id response header).
  request_id           text,                                                 -- Velexis X-Request-Id of the triggering API call.
  redacted             boolean NOT NULL DEFAULT true,                        -- * True when PII/card data were stripped from the bodies.
  request_body         jsonb,                                                -- Request body / query after the redaction rule (plus e-mails and phones masked).
  response_body        jsonb,                                                -- Response body after the redaction rule (may be truncated).
  truncated            boolean NOT NULL DEFAULT false,                       -- Bodies were truncated to the size limit.
  booking_id           text REFERENCES bookings (id) ON DELETE SET NULL,     -- * Related booking.
  search_id            text REFERENCES flight_searches (id) ON DELETE SET NULL, -- * Related search.
  staff_id             text,                                                 -- Staff id (stf_) by value for console calls.
  created_at           timestamptz NOT NULL DEFAULT now(),                   -- * Call time (retention purge after 90 days).
  updated_at           timestamptz NOT NULL DEFAULT now()                    -- Equal to created_at (append-only).
);
CREATE INDEX supplier_requests_created_idx ON supplier_requests (environment, created_at DESC, id DESC);
CREATE INDEX supplier_requests_booking_idx ON supplier_requests (booking_id, created_at DESC) WHERE booking_id IS NOT NULL;
CREATE INDEX supplier_requests_search_idx ON supplier_requests (search_id) WHERE search_id IS NOT NULL;
CREATE INDEX supplier_requests_api_idx ON supplier_requests (environment, amadeus_api, created_at DESC);
CREATE INDEX supplier_requests_staff_idx ON supplier_requests (environment, staff_id, created_at DESC) WHERE staff_id IS NOT NULL;
CREATE INDEX supplier_requests_error_codes_idx ON supplier_requests USING gin (error_codes);
CREATE INDEX supplier_requests_correlation_idx ON supplier_requests (correlation_id) WHERE correlation_id IS NOT NULL;
CREATE INDEX supplier_requests_request_idx ON supplier_requests (request_id) WHERE request_id IS NOT NULL;

-- Append-only booking history (creation, payment, ticketing, changes, sync, cancellation) for timelines and audit.
CREATE TABLE booking_events (
  id                  text PRIMARY KEY CHECK (id LIKE 'evt\_%'),             -- Event id (evt_ + ULID).
  booking_id          text NOT NULL REFERENCES bookings (id) ON DELETE CASCADE, -- * Booking.
  type                text NOT NULL,                                         -- * Event type, e.g. booking.created, booking.ticketed, booking.synced, booking.schedule_changed.
  actor_type          text NOT NULL CHECK (actor_type IN ('customer','guest','staff','system','supplier','api_key')), -- * Who caused it.
  actor_id            text,                                                  -- cus_ / stf_ / key_ id by value.
  status_from         text,                                                  -- Booking status before.
  status_to           text,                                                  -- Booking status after.
  summary             text,                                                  -- Human-readable line for the timeline.
  data                jsonb NOT NULL DEFAULT '{}'::jsonb,                    -- Details / diff, written after the redaction rule (no document, discount or card numbers, no tokens).
  visible_to_customer boolean NOT NULL DEFAULT true,                         -- Whether customer scope shows it.
  supplier_request_id text REFERENCES supplier_requests (id) ON DELETE SET NULL, -- Amadeus call behind the event.
  request_id          text,                                                  -- X-Request-Id.
  created_at          timestamptz NOT NULL DEFAULT now(),                    -- * Event time.
  updated_at          timestamptz NOT NULL DEFAULT now()                     -- Equal to created_at (append-only).
);
CREATE INDEX booking_events_booking_idx ON booking_events (booking_id, created_at);
CREATE INDEX booking_events_supplier_request_idx ON booking_events (supplier_request_id) WHERE supplier_request_id IS NOT NULL;

-- Results of Amadeus Queue List calls (office queue PNR lists) fetched by staff or the queue poller.
CREATE TABLE queue_snapshots (
  id                  text PRIMARY KEY CHECK (id LIKE 'qsn\_%'),             -- Snapshot id (qsn_ + ULID).
  environment         text NOT NULL CHECK (environment IN ('test','live')),  -- * Amadeus environment.
  office_id           text NOT NULL,                                         -- * officeId queried.
  queue_id            integer NOT NULL CHECK (queue_id >= 0),                -- * queue-id path parameter.
  category            integer NOT NULL DEFAULT 0 CHECK (category >= 0),      -- * category query parameter (default 0).
  max_requested       integer CHECK (max_requested > 0),                     -- max query parameter.
  item_count          integer NOT NULL DEFAULT 0 CHECK (item_count >= 0),    -- * meta.count / number of PNRs returned.
  response            jsonb NOT NULL,                                        -- Verbatim response (data[] pnrs, warnings, meta).
  fetched_by_staff_id text,                                                  -- Staff id (stf_) by value (NULL = scheduled poller).
  supplier_request_id text REFERENCES supplier_requests (id) ON DELETE SET NULL, -- Underlying Amadeus call.
  fetched_at          timestamptz NOT NULL DEFAULT now(),                    -- * When the queue was read.
  created_at          timestamptz NOT NULL DEFAULT now(),                    -- Row creation time.
  updated_at          timestamptz NOT NULL DEFAULT now()                     -- Equal to created_at (append-only).
);
CREATE INDEX queue_snapshots_queue_idx ON queue_snapshots (environment, office_id, queue_id, category, fetched_at DESC);
CREATE INDEX queue_snapshots_fetched_idx ON queue_snapshots (environment, fetched_at DESC, id DESC);
CREATE INDEX queue_snapshots_supplier_request_idx ON queue_snapshots (supplier_request_id) WHERE supplier_request_id IS NOT NULL;

-- Notification outbox (e-mails / SMS to customers, guests and staff), drained by a worker with SKIP LOCKED.
-- Token-bearing variables (verification / reset links, guest booking tokens) go only into secret_payload_ciphertext,
-- which must be purged (NULL) as soon as the message leaves pending/sending (sent, delivered, bounced, failed, cancelled).
CREATE TABLE notifications (
  id                  text PRIMARY KEY CHECK (id LIKE 'ntf\_%'),             -- Notification id (ntf_ + ULID).
  template_id         text REFERENCES notification_templates (id) ON DELETE SET NULL, -- * Template used.
  template_key        text NOT NULL,                                         -- * Template key (kept if the template is deleted).
  channel             text NOT NULL CHECK (channel IN ('email','sms')),      -- * Delivery channel.
  recipient           text NOT NULL,                                         -- * E-mail address or E.164 phone number.
  recipient_type      text NOT NULL CHECK (recipient_type IN ('customer','guest','staff')), -- Recipient kind.
  customer_id         text REFERENCES customers (id) ON DELETE SET NULL,     -- Customer recipient.
  booking_id          text REFERENCES bookings (id) ON DELETE SET NULL,      -- * Booking the message is about.
  locale              text NOT NULL DEFAULT 'en',                            -- Rendering locale.
  subject             text,                                                  -- Rendered subject.
  payload             jsonb NOT NULL DEFAULT '{}'::jsonb,                    -- Non-secret template variables (redaction rule applies; never raw tokens or token-bearing links).
  secret_payload_ciphertext bytea,                                           -- Encrypted secret variables (verification / reset link token, guest booking token) merged in at render time.
  encryption_key_id   text,                                                  -- KMS key id wrapping the data key of secret_payload_ciphertext.
  secrets_purged_at   timestamptz,                                           -- When secret_payload_ciphertext was erased (after the final delivery outcome).
  attachments         jsonb NOT NULL DEFAULT '[]'::jsonb,                    -- booking_documents ids to attach.
  dedupe_key          text,                                                  -- Idempotency of sends, e.g. booking.ticketed:bkg_...
  status              text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','sending','sent','delivered','bounced','failed','cancelled')), -- * Delivery state.
  attempts            integer NOT NULL DEFAULT 0 CHECK (attempts >= 0),      -- Delivery attempts.
  next_attempt_at     timestamptz NOT NULL DEFAULT now(),                    -- * When the worker may (re)try.
  last_error          text,                                                  -- Last delivery error.
  provider            text,                                                  -- E-mail/SMS provider used.
  provider_message_id text,                                                  -- Provider message id (bounce webhooks).
  sent_at             timestamptz,                                           -- Hand-over time to the provider.
  created_at          timestamptz NOT NULL DEFAULT now(),                    -- * Enqueue time.
  updated_at          timestamptz NOT NULL DEFAULT now(),                    -- Last modification time.
  CONSTRAINT notifications_secret_key_ck CHECK (secret_payload_ciphertext IS NULL OR encryption_key_id IS NOT NULL),
  CONSTRAINT notifications_secret_purge_ck CHECK (secret_payload_ciphertext IS NULL OR status IN ('pending','sending'))
);
CREATE INDEX notifications_outbox_idx ON notifications (next_attempt_at) WHERE status = 'pending';
CREATE UNIQUE INDEX notifications_dedupe_uq ON notifications (dedupe_key) WHERE dedupe_key IS NOT NULL;
CREATE INDEX notifications_booking_idx ON notifications (booking_id) WHERE booking_id IS NOT NULL;
CREATE INDEX notifications_customer_idx ON notifications (customer_id, created_at DESC) WHERE customer_id IS NOT NULL;
CREATE INDEX notifications_template_idx ON notifications (template_id) WHERE template_id IS NOT NULL;

-- Console audit trail: every console action with before/after state. The actor is a staff member (stf_, from
-- platform by value), the secret API key used without a staff token (key_), or the system; failed staff sign-ins
-- carry only the e-mail snapshot.
CREATE TABLE staff_actions (
  id          text PRIMARY KEY CHECK (id LIKE 'sact\_%'),                    -- Staff action id (sact_ + ULID).
  actor_type  text NOT NULL DEFAULT 'staff' CHECK (actor_type IN ('staff','api_key','system')), -- * Who acted (ConsoleActor.type).
  actor_id    text,                                                          -- * stf_ (= staff_id) or key_ (platform.api_keys) id by value; NULL for system and unidentified sign-in attempts.
  staff_id    text CHECK (staff_id LIKE 'stf\_%'),                           -- * platform.tenant_memberships id, by value (NULL for API-key and system actions and failed sign-ins).
  account_id  text,                                                          -- platform.accounts id (acc_) by value.
  staff_email text,                                                          -- Snapshot of the staff e-mail (the only identity of a failed sign-in).
  staff_role  text CHECK (staff_role IN ('owner','admin','agent','finance','viewer')), -- Role at the time of the action.
  action      text NOT NULL,                                                 -- * Action, e.g. booking.cancel, order.patch, booking.issue, pnr.lookup, queue.list.
  target_type text,                                                          -- * Affected object type (booking, customer, markup_rule ...).
  target_id   text,                                                          -- * Affected object id.
  booking_id  text REFERENCES bookings (id) ON DELETE SET NULL,              -- * Booking concerned (shortcut for booking timelines).
  reason      text,                                                          -- Justification entered by the staff member.
  before      jsonb,                                                         -- State before the action, after the redaction rule (documents, discount and card numbers masked, CVV and tokens dropped).
  after       jsonb,                                                         -- State after the action, same redaction rule.
  outcome     text NOT NULL DEFAULT 'succeeded' CHECK (outcome IN ('succeeded','failed','denied')), -- * Result.
  request_id  text,                                                          -- X-Request-Id.
  ip_address  inet,                                                          -- Client IP.
  user_agent  text,                                                          -- Client user agent.
  created_at  timestamptz NOT NULL DEFAULT now(),                            -- * Action time.
  updated_at  timestamptz NOT NULL DEFAULT now(),                            -- Equal to created_at (append-only).
  CONSTRAINT staff_actions_actor_ck CHECK (
    (actor_type = 'staff' AND staff_id IS NOT NULL AND actor_id = staff_id)
    OR (actor_type = 'staff' AND staff_id IS NULL AND actor_id IS NULL AND staff_email IS NOT NULL AND outcome IN ('failed','denied'))
    OR (actor_type = 'api_key' AND actor_id LIKE 'key\_%' AND staff_id IS NULL)
    OR (actor_type = 'system' AND actor_id IS NULL AND staff_id IS NULL))
);
CREATE INDEX staff_actions_staff_idx ON staff_actions (staff_id, created_at DESC) WHERE staff_id IS NOT NULL;
CREATE INDEX staff_actions_actor_idx ON staff_actions (actor_type, actor_id, created_at DESC);
CREATE INDEX staff_actions_target_idx ON staff_actions (target_type, target_id);
CREATE INDEX staff_actions_booking_idx ON staff_actions (booking_id) WHERE booking_id IS NOT NULL;
CREATE INDEX staff_actions_created_idx ON staff_actions (created_at DESC);

-- Idempotency-Key records for state-changing POSTs (replay the stored response; reject a different body).
-- A response that carries a token (bookingToken, session tokens) or unmasked traveller data is replayed only from
-- response_ciphertext; response_body always holds the redacted copy (diagnostics, non-secret replays).
CREATE TABLE idempotency_keys (
  id               text PRIMARY KEY CHECK (id LIKE 'idk\_%'),                -- Record id (idk_ + ULID).
  scope            text NOT NULL,                                            -- * Principal + environment + operation, e.g. live:key_123:checkouts.create or live:cus_9:bookings.cancel.
  key              text NOT NULL CHECK (length(key) BETWEEN 1 AND 255),      -- * Idempotency-Key header value.
  request_method   text NOT NULL,                                            -- HTTP method.
  request_path     text NOT NULL,                                            -- Request path.
  request_hash     text NOT NULL,                                            -- * SHA-256 of the canonical request body (IDEMPOTENCY_KEY_REUSED on mismatch).
  status           text NOT NULL DEFAULT 'processing' CHECK (status IN ('processing','completed','failed')), -- * Processing state.
  locked_until     timestamptz,                                              -- Lease of the in-flight request (concurrent retries get 409).
  response_status  smallint,                                                 -- Stored HTTP status.
  response_headers jsonb,                                                    -- Stored relevant headers.
  response_body    jsonb,                                                    -- Stored response body after the redaction rule (never a raw token, document or card number).
  response_ciphertext bytea,                                                 -- Encrypted verbatim response body, set when it carries tokens or unmasked data; the replay source then.
  encryption_key_id text,                                                    -- KMS key id wrapping the data key of response_ciphertext.
  resource_type    text,                                                     -- Type of the created/changed resource.
  resource_id      text,                                                     -- Id of the created/changed resource (e.g. bkg_...).
  expires_at       timestamptz NOT NULL,                                     -- * Retention end (24 h), purge job.
  created_at       timestamptz NOT NULL DEFAULT now(),                       -- First request time.
  updated_at       timestamptz NOT NULL DEFAULT now(),                       -- Last modification time.
  CONSTRAINT idempotency_keys_scope_key_uq UNIQUE (scope, key),
  CONSTRAINT idempotency_keys_ciphertext_ck CHECK (response_ciphertext IS NULL OR encryption_key_id IS NOT NULL)
);
CREATE INDEX idempotency_keys_expires_idx ON idempotency_keys (expires_at);
